    factors.add(2);
    n = n ~/ 2;
  }

  // n must be odd at this point
  int factor = 3;
  final sqrtN = sqrt(n).toInt();

  // Check odd factors up to sqrt(n)
  while (factor <= sqrtN) {
    while (n % factor == 0) {
      factors.add(factor);
      n = n ~/ factor;
    }
    factor += 2;
  }

  // Handle remaining prime factor
  if (n > 2) {
    factors.add(n);
  }

  return factors;
}
