```dart
import 'dart:math';

int? pollardsRho(int n) {
  // Handle even numbers
  if (n.isEven) return 2;

  final random = Random();
  final bitLength = n.bitLength;
  final bound = max(1, bitLength - 1); // Ensure bound >=1

  // Initialize random parameters
  final c = random.nextInt(bound);
  int y = random.nextInt(bound);

  // Initial sequence values
  int x = (y * y + c) % n;
  int temp = (x * x + c) % n;

  while (true) {
    // Next values in sequence
    final yNext = (y * y + c) % n;
    temp = (yNext * yNext + c) % n;

    // Compute absolute difference
    int diff = (x - temp).abs();

    // Calculate GCD and check for factor
    final d = gcd(diff, n);
    if (d > 1 && d < n) return d;  // Non-trivial factor found
    if (d == 1) {                   // Continue loop if no collision
      x = yNext;
      y = temp;
    } else {
      return d;  // Return trivial factor (d == n)
    }
  }
}

// Helper GCD function (Euclidean algorithm)
int gcd(int a, int b) {
  while (b != 0) {
    final t = b;
    b = a % b;
    a = t;
  }
  return a;
}
```

