Future<void> main() async {
  // Start a simple WebSocket echo server
  final server = await HttpServer.bind('localhost', 8080);
  print('WebSocket server running at ws://localhost:8080');

  // Handle WebSocket connections
  server.transform(WebSocketTransformer()).listen((WebSocket ws) {
    print('Client connected');
    Timer? pingTimer;

    // Send ping every 5 seconds
    pingTimer = Timer.periodic(Duration(seconds: 5), (timer) {
      print('Server: Sending ping');
      ws.add(jsonEncode({'type': 'ping'}));
    });

    ws.listen((message) {
      print('Server: Received: $message');
      try {
        final data = jsonDecode(message);
        if (data is Map && data['type'] == 'pong') {
          print('Server: Received pong from client');
        }
      } catch (_) {}
    }, onDone: () {
      pingTimer?.cancel();
      print('Client disconnected');
    });
  });

  // Give server a moment to start
  await Future.delayed(Duration(seconds: 1));

  // Connect as client
  final wsClient = await WebSocket.connect('ws://localhost:8080');
  print('Client: Connected to server');

  // Respond to ping, send pong
  wsClient.listen((message) {
    print('Client: Received: $message');
    try {
      final data = jsonDecode(message);
      if (data is Map && data['type'] == 'ping') {
        print('Client: Sending pong');
        wsClient.add(jsonEncode({'type': 'pong'}));
      }
    } catch (_) {}
  });

  // Keep the program running for 20 seconds
  await Future.delayed(Duration(seconds: 20));
  await wsClient.close();
  await server.close(force: true);
  print('Closed server and client');
}

