void main() {
  // Ford-Fulkerson algorithm for maximum flow problem

  // Graph represented as adjacency matrix
  // Example network with 6 nodes (0 to 5)
  // 0 is source, 5 is sink
  final int vertices = 6;
  List<List<int>> graph = [
    //  0   1   2   3   4   5
    [  0, 16, 13,  0,  0,  0], // 0
    [  0,  0, 10, 12,  0,  0], // 1
    [  0,  4,  0,  0, 14,  0], // 2
    [  0,  0,  9,  0,  0, 20], // 3
    [  0,  0,  0,  7,  0,  4], // 4
    [  0,  0,  0,  0,  0,  0], // 5
  ];

  // Create residual graph and initialize with original capacities
  List<List<int>> residualGraph = List.generate(
    vertices, 
    (i) => List.from(graph[i])
  );

  // BFS to find augmenting path from source to sink
  bool bfs(List<List<int>> rGraph, int source, int sink, List<int> parent) {
    List<bool> visited = List.filled(vertices, false);
    List<int> queue = [];

    queue.add(source);
    visited[source] = true;
    parent[source] = -1;

    while (queue.isNotEmpty) {
      int u = queue.removeAt(0);

      for (int v = 0; v < vertices; v++) {
        if (!visited[v] && rGraph[u][v] > 0) {
          queue.add(v);
          parent[v] = u;
          visited[v] = true;

          if (v == sink) {
            return true;
          }
        }
      }
    }

    return false;
  }

  // Ford-Fulkerson algorithm
  int fordFulkerson(int source, int sink) {
    List<int> parent = List.filled(vertices, 0);
    int maxFlow = 0;

    // While there exists an augmenting path from source to sink
    while (bfs(residualGraph, source, sink, parent)) {
      // Find minimum residual capacity along the path
      int pathFlow = 999999999; // Use large number as infinity

      for (int v = sink; v != source; v = parent[v]) {
        int u = parent[v];
        if (residualGraph[u][v] < pathFlow) {
          pathFlow = residualGraph[u][v];
        }
      }

      // Update residual capacities of edges and reverse edges
      for (int v = sink; v != source; v = parent[v]) {
        int u = parent[v];
        residualGraph[u][v] -= pathFlow;
        residualGraph[v][u] += pathFlow;
      }

      // Add path flow to overall flow
      maxFlow += pathFlow;

      // Print augmenting path details
      print('Found augmenting path with flow: $pathFlow');
      List<int> path = [];
      for (int v = sink; v != -1; v = parent[v]) {
        path.insert(0, v);
      }
      print('Path: ${path.join(' -> ')}');
    }

    return maxFlow;
  }

  // Print original graph
  print('Original Graph (Capacity Matrix):');
  print('     0   1   2   3   4   5');
  for (int i = 0; i < vertices; i++) {
    String row = '$i: ';
    for (int j = 0; j < vertices; j++) {
      row += graph[i][j].toString().padLeft(4);
    }
    print(row);
  }
  print('');

  // Find maximum flow from source (0) to sink (5)
  int source = 0;
  int sink = 5;

  print('Finding maximum flow from node $source to node $sink...\n');
  int maxFlow = fordFulkerson(source, sink);

  print('\nMaximum flow from source to sink: $maxFlow');

  // Print final residual graph to show flow distribution
  print('\nFinal Residual Graph:');
  print('     0   1   2   3   4   5');
  for (int i = 0; i < vertices; i++) {
    String row = '$i: ';
    for (int j = 0; j < vertices; j++) {
      row += residualGraph[i][j].toString().padLeft(4);
    }
    print(row);
  }

  // Calculate and display actual flow through each edge
  print('\nActual flow through edges:');
  for (int i = 0; i < vertices; i++) {
    for (int j = 0; j < vertices; j++) {
      if (graph[i][j] > 0) {
        int flow = graph[i][j] - residualGraph[i][j];
        if (flow > 0) {
          print('Edge ($i -> $j): $flow / ${graph[i][j]}');
        }
      }
    }
  }
}

