// Color class
class Color {
  final int value;

  Color(this.value);

  int get red => (value >> 16) & 0xFF;
  int get green => (value >> 8) & 0xFF;
  int get blue => value & 0xFF;

  Color interpolate(Color other, double t) {
    var r = (red + (other.red - red) * t).round();
    var g = (green + (other.green - green) * t).round();
    var b = (blue + (other.blue - blue) * t).round();
    return Color((r << 16) | (g << 8) | b | 0xFF000000);
  }

  double get luminance {
    double r = red / 255.0;
    double g = green / 255.0;
    double b = blue / 255.0;

    r = r <= 0.03928 ? r / 12.92 : ((r + 0.055) / 1.055) * ((r + 0.055) / 1.055);
    g = g <= 0.03928 ? g / 12.92 : ((g + 0.055) / 1.055) * ((g + 0.055) / 1.055);
    b = b <= 0.03928 ? b / 12.92 : ((b + 0.055) / 1.055) * ((b + 0.055) / 1.055);

    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
  }

  @override
  String toString() => '#${value.toRadixString(16).padLeft(8, '0').substring(2)}';
}

// Theme class
class Theme {
  final String name;
  final Color primaryColor;
  final Color secondaryColor;
  final Color backgroundColor;
  final Color textColor;
  final bool isDark;

  Theme({
    required this.name,
    required this.primaryColor,
    required this.secondaryColor,
    required this.backgroundColor,
    required this.textColor,
    required this.isDark,
  });

  static Theme interpolate(Theme start, Theme end, double t) {
    return Theme(
      name: 'Transition',
      primaryColor: start.primaryColor.interpolate(end.primaryColor, t),
      secondaryColor: start.secondaryColor.interpolate(end.secondaryColor, t),
      backgroundColor: start.backgroundColor.interpolate(end.backgroundColor, t),
      textColor: start.textColor.interpolate(end.textColor, t),
      isDark: t > 0.5 ? end.isDark : start.isDark,
    );
  }
}

// Theme Manager
class ThemeManager {
  Theme currentTheme;
  final List<Theme> themeHistory = [];

  ThemeManager(this.currentTheme) {
    themeHistory.add(currentTheme);
  }

  void switchTheme(Theme newTheme) {
    currentTheme = newTheme;
    themeHistory.add(newTheme);
    if (themeHistory.length > 10) {
      themeHistory.removeAt(0);
    }
  }

  void displayThemeInfo() {
    print('Current Theme: ${currentTheme.name}');
    print('  Primary: ${currentTheme.primaryColor}');
    print('  Secondary: ${currentTheme.secondaryColor}');
    print('  Background: ${currentTheme.backgroundColor}');
    print('  Text: ${currentTheme.textColor}');
    print('  Mode: ${currentTheme.isDark ? "Dark" : "Light"}');
  }
}

// Component types
enum ComponentType { header, navigation, content, footer }

// UI Component
class UIComponent {
  final String name;
  final ComponentType type;
  Color? backgroundColor;
  Color? textColor;

  UIComponent(this.name, this.type);

  void applyTheme(Theme theme) {
    switch (type) {
      case ComponentType.header:
        backgroundColor = theme.primaryColor;
        textColor = theme.isDark ? Color(0xFFFFFFFF) : Color(0xFFFFFFFF);
        break;
      case ComponentType.navigation:
        backgroundColor = theme.secondaryColor;
        textColor = theme.isDark ? Color(0xFFFFFFFF) : Color(0xFF000000);
        break;
      case ComponentType.content:
        backgroundColor = theme.backgroundColor;
        textColor = theme.textColor;
