  // Kahn's Algorithm for Topological Sort
  Map<int, int> inDegree = {};
  List<int> topologicalOrder = [];
  List<int> queue = [];

  // Initialize in-degree for all vertices
  for (int vertex in graph.keys) {
    inDegree[vertex] = 0;
  }

  // Calculate in-degree for each vertex
  for (var edges in graph.values) {
    for (int vertex in edges) {
      inDegree[vertex] = (inDegree[vertex] ?? 0) + 1;
    }
  }

  // Find all vertices with in-degree 0
  for (var entry in inDegree.entries) {
    if (entry.value == 0) {
      queue.add(entry.key);
    }
  }

  // Process vertices with in-degree 0
  while (queue.isNotEmpty) {
    int current = queue.removeAt(0);
    topologicalOrder.add(current);

    // Reduce in-degree for neighbors
    for (int neighbor in graph[current] ?? []) {
      inDegree[neighbor] = inDegree[neighbor]! - 1;
      if (inDegree[neighbor] == 0) {
        queue.add(neighbor);
      }
    }
  }

  // Check if topological sort is possible (no cycles)
  if (topologicalOrder.length != graph.length) {
    print("\nError: Graph contains a cycle! Topological sort not possible.");
  } else {
