// Cuckoo Hashing Demo in Dart

@pragma('vm:entry-point')
void main() {
  final int size = 11;
  final int maxKicks = 500;
  final int prime = 1000003;
  final int a1 = 17, b1 = 31, a2 = 29, b2 = 47;

  // Two tables for cuckoo hashing
  List<int?> table1 = List<int?>.filled(size, null);
  List<int?> table2 = List<int?>.filled(size, null);

  // Two independent hash functions
  int h1(int x) => ((a1 * x + b1) % prime) % size;
  int h2(int x) => ((a2 * x + b2) % prime) % size;

  // Lookup operation
  bool lookup(int key) {
    if (table1[h1(key)] == key) return true;
    if (table2[h2(key)] == key) return true;
    return false;
  }

  // Insert operation with limited kicks
  bool insert(int key) {
    if (lookup(key)) return false; // already present
    int curr = key;
    int table = 1;
    for (int kick = 0; kick < maxKicks; kick++) {
      if (table == 1) {
        int idx = h1(curr);
        if (table1[idx] == null) {
          table1[idx] = curr;
          return true;
        } else {
          // Evict occupant
          int evicted = table1[idx]!;
          table1[idx] = curr;
          curr = evicted;
          table = 2;
        }
      } else {
        int idx = h2(curr);
        if (table2[idx] == null) {
          table2[idx] = curr;
          return true;
        } else {
          int evicted = table2[idx]!;
          table2[idx] = curr;
          curr = evicted;
          table = 1;
        }
      }
    }
    print('Insertion of $key failed after $maxKicks kicks. Need rehash.');
    return false;
  }

  // Deletion operation
  bool delete(int key) {
    int i1 = h1(key);
    if (table1[i1] == key) {
      table1[i1] = null;
      return true;
    }
    int i2 = h2(key);
    if (table2[i2] == key) {
      table2[i2] = null;
      return true;
    }
    return false;
  }

  // Demonstration
  List<int> keys = [20, 50, 53, 75, 100, 67, 105, 3, 36, 39, 11];
  print('Inserting keys: $keys');
  for (var key in keys) {
    bool ok = insert(key);
    print('Insert $key: ${ok ? "Success" : "Failure"}');
  }

  print('\nFinal Tables:');
  print('Table1: $table1');
  print('Table2: $table2\n');

  // Lookup demonstration
  for (var key in keys) {
    print('Lookup $key: ${lookup(key)}');
  }

  // Deletion demonstration
  int delKey = keys[3]; // e.g., 75
  print('\nDeleting $delKey: ${delete(delKey)}');
  print('Lookup $delKey after deletion: ${lookup(delKey)}');
  print('\nTables after deletion:');
  print('Table1: $table1');
  print('Table2: $table2');
}

