import 'dart:convert';

@pragma('vm:entry-point')
void main() {
  dynamic customJsonEncode(dynamic value) {
    if (value == null) {
      return 'null';
    } else if (value is num || value is bool) {
      return value.toString();
    } else if (value is String) {
      // Escape special JSON characters in strings
      final escaped = value
          .replaceAll(r'\', r'\\')
          .replaceAll('"', r'\"')
          .replaceAll('\b', r'\b')
          .replaceAll('\f', r'\f')
          .replaceAll('\n', r'\n')
          .replaceAll('\r', r'\r')
          .replaceAll('\t', r'\t');
      return '"$escaped"';
    } else if (value is List) {
      return '[${value.map(customJsonEncode).join(',')}]';
    } else if (value is Map) {
      return '{' +
          value.entries
              .map((e) =>
                  '${customJsonEncode(e.key.toString())}:${customJsonEncode(e.value)}')
              .join(',') +
          '}';
    } else {
      throw ArgumentError('Unsupported type: ${value.runtimeType}');
    }
  }

  // Test data
  final data = {
    'name': 'Dart',
    'version': 3,
    'features': ['null safety', 'fast', 'portable'],
    'openSource': true,
    'nested': {
      'list': [1, 2, 3],
      'emptyMap': {},
      'nullValue': null,
    },
    'specialChars': 'He said: "Hello\nWorld"\tTab'
  };

  final customEncoded = customJsonEncode(data);
  final dartEncoded = jsonEncode(data);

  print('Custom JSON:');
  print(customEncoded);
  print('\nDart jsonEncode:');
  print(dartEncoded);
  print('\nAre they equal? ${customEncoded == dartEncoded}');
}

