// Run with: dart run <filename>.dart

@pragma('vm:entry-point') // Prevents `main` from being tree-shaken.
void main() {
  // A heterogeneous list that intentionally contains some nulls.
  final List<Object?> samples = [
    42,
    'Hello',
    null,
    3.14,
    {'key': 'value'},
    'World',
    null,
  ];

  // Use a switch expression with null-check patterns to handle the values.
  for (final value in samples) {
    switch (value) {
      // Matches a non-null int and promotes it to `int`.
      case int? n?:
        print('Non-null int  : $n → squared = ${n * n}');
      // Matches a non-null String and promotes it to `String`.
      case String? s?:
        print('Non-null String: "$s" → length  = ${s.length}');
      // Matches a non-null double and promotes it to `double`.
      case double? d?:
        print('Non-null double: $d → rounded = ${d.round()}');
      // Matches an explicit null.
      case null:
        print('It is null.');
      // Any other, unmatched value.
      default:
        print('Some other type: $value');
    }
  }

  // ---------------------------------------------------------------
  // A quick `if-case` demo using the same null-check pattern.
  // ---------------------------------------------------------------
  Object? maybeName = 'Dart';
  if (maybeName case String? name?) {
    // `name` is promoted to non-null String here.
    print('\nHello, ${name.toUpperCase()}!');
  }

  maybeName = null;
  if (maybeName case String? _) {
    // This branch is not taken because the value is null.
    print('This will never print.');
  } else {
    print('\n`maybeName` is either null or not a String.');
  }
}

