import 'dart:async';

@pragma('vm:entry-point') // prevents the VM from tree-shaking away `main`
void main() {
  // Everything printed here illustrates the order in which the Dart runtime
  // drains the microtask queue versus the regular event queue.

  print('1) main() begins');

  // ---------- Microtasks ----------
  // scheduleMicrotask() pushes callbacks onto the microtask queue, which is
  // always drained before the event queue is touched again.

  scheduleMicrotask(() => print('2) first microtask'));

  scheduleMicrotask(() {
    print('3) second microtask (start)');
    // A microtask can enqueue more microtasks; they run immediately after the
    // current microtask finishes, before the event queue resumes.
    scheduleMicrotask(() => print('4) nested microtask inside second'));
    print('5) second microtask (end)');
  });

  // ---------- Event-queue (macro) tasks ----------
  // A zero-duration Future or Future.delayed pushes work onto the event queue,
  // which is only serviced after the current microtask queue is empty.

  Future(() => print('6) event task from Future()'));
  Future.delayed(Duration.zero, () => print('7) event task from Future.delayed'));

  // A regular Timer does the same thing (macro-task).
  Timer.run(() => print('8) event task from Timer.run'));

  print('9) main() ends');
}

