import 'dart:async';
import 'dart:math';

/// A simple Dart program that simulates location-based push notifications.
/// It periodically checks a simulated location and "pushes" a notification
/// (by printing to console) if the simulated location is within a certain range
/// of a target location. This is a console-based simulation for demonstration
/// purposes, as pure Dart does not have built-in location or notification APIs.
/// In a real app, you'd use packages like geolocator and firebase_messaging in Flutter.

@pragma('vm:entry-point')
void main() async {
  // Target location (latitude, longitude)
  const double targetLat = 37.7749; // Example: San Francisco
  const double targetLon = -122.4194;
  const double notificationRadiusKm = 1.0; // Notify if within 1 km

  // Timer to check location every 5 seconds
  Timer.periodic(Duration(seconds: 5), (timer) {
    // Simulate getting current location with some randomness
    final random = Random();
    final currentLat = targetLat + (random.nextDouble() - 0.5) * 0.02; // Vary by ~1-2 km
    final currentLon = targetLon + (random.nextDouble() - 0.5) * 0.02;

    // Calculate distance to target (simple Haversine formula approximation)
    const double earthRadiusKm = 6371.0;
    final double dLat = _degreesToRadians(currentLat - targetLat);
    final double dLon = _degreesToRadians(currentLon - targetLon);
    final double a = sin(dLat / 2) * sin(dLat / 2) +
        cos(_degreesToRadians(targetLat)) * cos(_degreesToRadians(currentLat)) *
            sin(dLon / 2) * sin(dLon / 2);
    final double c = 2 * atan2(sqrt(a), sqrt(1 - a));
    final double distance = earthRadiusKm * c;

    // Check if within radius
    if (distance <= notificationRadiusKm) {
      // Simulate pushing a notification by printing to console
      print('Push Notification: You are near the target location! '
