// A complete Dart program demonstrating abstract classes used as mixins.
// In Dart, mixins are typically declared with the 'mixin' keyword, which
// creates an abstract class-like structure for code reuse.

import 'dart:io';

// Define a mixin (abstract class-like) for logging functionality.
mixin Logger {
  void log(String message) {
    print('Log: $message');
  }

  // Abstract method to be implemented by the class using the mixin.
  String getDescription();
}

// A concrete class that uses the Logger mixin.
class MyApplication with Logger {
  final String name;

  MyApplication(this.name);

  @override
  String getDescription() {
    return 'Application name: $name';
  }

  void run() {
    log('Starting application...');
    print(getDescription());
    log('Application running.');
  }
}

@pragma('vm:entry-point')
void main() {
  // Create an instance of MyApplication which uses the Logger mixin.
  final app = MyApplication('My Dart App');
  app.run();

  // Exit the program cleanly.
  exit(0);
}

