  // Define the survey questions
  List<Map<String, dynamic>> questions = [
    {
      'question': 'What is your age group?',
      'type': 'multiple_choice',
      'options': ['Under 18', '18-24', '25-34', '35-44', '45+']
    },
    {
      'question': 'How satisfied are you with our app? (1-5)',
      'type': 'rating',
    },
    {
      'question': 'What features would you like to see added?',
      'type': 'open_ended',
    },
  ];

  // Store user responses
  Map<String, String> responses = {};

  print('Welcome to the In-App Survey!');
  print('Please answer the following questions:\n');

  // Loop through each question and collect responses
  for (var q in questions) {
    print('Question: ${q['question']}');

    if (q['type'] == 'multiple_choice') {
      print('Options:');
      for (int i = 0; i < q['options'].length; i++) {
        print('${i + 1}. ${q['options'][i]}');
      }
      stdout.write('Enter your choice (1-${q['options'].length}): ');
      String? input = stdin.readLineSync();
      try {
        int choice = int.parse(input ?? '0');
        if (choice >= 1 && choice <= q['options'].length) {
          responses[q['question']] = q['options'][choice - 1];
        } else {
          responses[q['question']] = 'Invalid choice';
        }
      } catch (e) {
        responses[q['question']] = 'Invalid input';
      }
    } else if (q['type'] == 'rating') {
      stdout.write('Enter a number between 1 and 5: ');
      String? input = stdin.readLineSync();
      responses[q['question']] = input ?? 'No response';
    } else if (q['type'] == 'open_ended') {
      stdout.write('Your answer: ');
      String? input = stdin.readLineSync();
      responses[q['question']] = input ?? 'No response';
    }

    print(''); // Add a newline for spacing
  }

  // Display survey summary
  print('Thank you for completing the survey!');
  print('Your responses:');
  responses.forEach((question, response) {
    print('$question: $response');
  });
}

