class Distance {
  final double meters;

  // Private generative const constructor that actually stores the value.
  const Distance._internal(this.meters);

  // Public generative const constructor that accepts meters directly.
  const Distance.meters(double meters) : this._internal(meters);

  // Redirecting const constructor: accepts kilometers, redirects to a private
  // constructor that does the conversion. Note the '=' syntax.
  const factory Distance.kilometers(double kilometers) =
      Distance._fromKilometers;

  // Private named const constructor used solely for redirection.
  const Distance._fromKilometers(double km) : this._internal(km * 1000);

  @override
  String toString() => '$meters m';
}

@pragma('vm:entry-point')
void main() {
  // Both distances are compile-time constants thanks to const constructors.
  const Distance d1 = Distance.meters(2000);
  const Distance d2 = Distance.kilometers(2);

  print('d1: $d1'); // 2000.0 m
  print('d2: $d2'); // 2000.0 m

  // Because the two const objects evaluate to the same canonical instance,
  // identical returns true.
  print('identical(d1, d2) = ${identical(d1, d2)}');
}

