import 'dart:convert';
import 'dart:io';

@pragma('vm:entry-point')
void main(List<String> args) {
  /* ---------------------------------------------------------------
   * Simple in-app rating demo.
   *
   * • Keeps a tiny JSON file in the user’s home directory to track
   *   how many times the app has been opened and whether the user
   *   has already rated.
   * • After the third launch (and only if not yet rated) the user is
   *   prompted for a 1-to-5 star rating.
   * • Positive ratings (≥4) trigger a simulated “open the store”
   *   message; lower ratings ask for written feedback.
   * --------------------------------------------------------------*/

  // 1. Locate persistence file (cross-platform best-effort “home” dir).
  final String home = Platform.environment['HOME'] ??
      Platform.environment['USERPROFILE'] ?? // Windows fallback
      Directory.current.path;
  final File dbFile = File('$home/.rating_demo.json');

  // 2. Read or initialise data.
  Map<String, dynamic> data;
  if (dbFile.existsSync()) {
    try {
      data = jsonDecode(dbFile.readAsStringSync());
    } catch (_) {
      data = <String, dynamic>{};
    }
  } else {
    data = <String, dynamic>{};
  }

  // 3. Update launch counter.
  final int launches = (data['launches'] ?? 0) + 1;
  data['launches'] = launches;
  dbFile.writeAsStringSync(jsonEncode(data));

  stdout.writeln('Welcome to DemoApp! Launch count: $launches');

  // 4. Decide whether to ask for a rating.
  final bool alreadyRated = data['rated'] == true;
  const int threshold = 3; // prompt after n launches

  if (!alreadyRated && launches >= threshold) {
    stdout.write('Would you like to rate the app? (y/n) ');
    final String? consent = stdin.readLineSync()?.trim().toLowerCase();

    if (consent == 'y') {
      int? stars;
      while (stars == null || stars < 1 || stars > 5) {
        stdout.write('Please enter a rating from 1 (worst) to 5 (best): ');
        stars = int.tryParse(stdin.readLineSync() ?? '');
      }

      data
        ..['rated'] = true
        ..['rating'] = stars;

      if (stars >= 4) {
        stdout.write(
            'Thanks for the positive rating! Open the store page to leave a review? (y/n) ');
        if ((stdin.readLineSync() ?? '').trim().toLowerCase() == 'y') {
          stdout.writeln('Opening store page (simulated)…');
          // In a real mobile app you’d call `launchUrl(storeUrl);`
        } else {
          stdout.writeln('No problem, maybe later!');
        }
      } else {
        stdout.writeln(
            'We’re sorry the experience wasn’t perfect. What can we improve?');
        data['feedback'] = stdin.readLineSync() ?? '';
        stdout.writeln('Thank you for your feedback!');
      }

      // Persist updated rating/feedback.
      dbFile.writeAsStringSync(jsonEncode(data));
    } else {
      stdout.writeln('Okay, we won’t ask right now.');
    }
  }

  stdout.writeln('Goodbye!');
}

