// An extension type representing a temperature in Celsius.
extension type Temperature(double celsius) {
  // Convert to Fahrenheit.
  double toFahrenheit() => celsius * 9 / 5 + 32;

  // Check if below freezing point (0°C).
  bool get isBelowFreezing => celsius < 0;
}

// An extension type representing a distance in meters.
extension type Distance(double meters) {
  // Convert to kilometers.
  double toKilometers() => meters / 1000;

  // Check if the distance is longer than 1 kilometer.
  bool get isLong => meters > 1000;
}

@pragma('vm:entry-point')
void main() {
  // Demonstrate Temperature extension type.
  final summerDay = Temperature(25.0);
  final winterNight = Temperature(-5.0);

  print('Summer day: ${summerDay.celsius}°C = '
        '${summerDay.toFahrenheit().toStringAsFixed(1)}°F');
  print('Winter night: ${winterNight.celsius}°C = '
        '${winterNight.toFahrenheit().toStringAsFixed(1)}°F, '
        'below freezing? ${winterNight.isBelowFreezing}');

  // Demonstrate Distance extension type.
  final shortWalk = Distance(150.0);
  final marathon = Distance(42195.0);

  print('Short walk: ${shortWalk.meters} m = '
        '${shortWalk.toKilometers().toStringAsFixed(2)} km, '
        'long? ${shortWalk.isLong}');
  print('Marathon: ${marathon.meters} m = '
