// Binary search on a sorted list.
// Usage: dart run binary_search.dart [target]
@pragma('vm:entry-point')
void main(List<String> args) {
  // Example sorted list (ascending).
  final List<int> sorted = [-10, -3, 0, 1, 3, 5, 7, 9, 12, 13, 15, 18, 21, 34, 55];

  // Parse target from args if provided; else use a default.
  int target;
  if (args.isNotEmpty) {
    final parsed = int.tryParse(args[0]);
    if (parsed == null) {
      print('Invalid target "${args[0]}". Please provide an integer.');
      print('Example: dart run binary_search.dart 13');
      return;
    }
    target = parsed;
  } else {
    target = 13; // Default target if none provided.
  }

  // Iterative binary search.
  int left = 0;
  int right = sorted.length - 1;
  int index = -1;

  while (left <= right) {
    final int mid = left + ((right - left) >> 1); // Prevents potential overflow.
    final int value = sorted[mid];

    if (value == target) {
      index = mid;
      break;
    } else if (value < target) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  // Output results.
  print('List: $sorted');
  print('Target: $target');
  if (index >= 0) {
    print('Found at index $index');
  } else {
    print('Not found (-1)');
  }
}

