@pragma('vm:entry-point')
void main() {
  // Heavy-Light Decomposition implementation
  // Example tree with 10 nodes
  final int n = 10;

  // Adjacency list representation of tree
  List<List<int>> adj = List.generate(n, (_) => []);

  // Build example tree
  void addEdge(int u, int v) {
    adj[u].add(v);
    adj[v].add(u);
  }

  // Create a sample tree
  addEdge(0, 1);
  addEdge(0, 2);
  addEdge(1, 3);
  addEdge(1, 4);
  addEdge(2, 5);
  addEdge(2, 6);
  addEdge(3, 7);
  addEdge(4, 8);
  addEdge(4, 9);

  // HLD data structures
  List<int> parent = List.filled(n, -1);
  List<int> depth = List.filled(n, 0);
  List<int> heavy = List.filled(n, -1);
  List<int> head = List.filled(n, 0);
  List<int> pos = List.filled(n, 0);
  List<int> subtreeSize = List.filled(n, 0);
  int currentPos = 0;

  // DFS to calculate subtree sizes and find heavy edges
  int dfs(int v, int p, int d) {
    parent[v] = p;
    depth[v] = d;
    subtreeSize[v] = 1;
    int maxSubtree = 0;

    for (int u in adj[v]) {
      if (u != p) {
        int childSize = dfs(u, v, d + 1);
        subtreeSize[v] += childSize;
        if (childSize > maxSubtree) {
          maxSubtree = childSize;
          heavy[v] = u;
        }
      }
    }

    return subtreeSize[v];
  }

  // Decompose the tree into heavy and light edges
  void decompose(int v, int h) {
    head[v] = h;
    pos[v] = currentPos++;

    // First, traverse the heavy child
    if (heavy[v] != -1) {
      decompose(heavy[v], h);
    }

    // Then traverse light children
    for (int u in adj[v]) {
      if (u != parent[v] && u != heavy[v]) {
        decompose(u, u);
      }
    }
  }

  // Find LCA using HLD
  int findLCA(int u, int v) {
    while (head[u] != head[v]) {
      if (depth[head[u]] > depth[head[v]]) {
        u = parent[head[u]];
      } else {
        v = parent[head[v]];
      }
    }
    return depth[u] < depth[v] ? u : v;
  }

  // Query path between two nodes (returns list of chain segments)
  List<List<int>> queryPath(int u, int v) {
    List<List<int>> segments = [];

    while (head[u] != head[v]) {
      if (depth[head[u]] > depth[head[v]]) {
        segments.add([pos[head[u]], pos[u]]);
        u = parent[head[u]];
      } else {
        segments.add([pos[head[v]], pos[v]]);
        v = parent[head[v]];
      }
    }

    if (depth[u] > depth[v]) {
      segments.add([pos[v], pos[u]]);
    } else {
      segments.add([pos[u], pos[v]]);
    }

    return segments;
  }

  // Build HLD
  print('Building Heavy-Light Decomposition for tree with $n nodes');
  dfs(0, -1, 0);
  decompose(0, 0);

  // Print HLD information
  print('\nNode Information:');
  print('Node | Parent | Depth | Heavy Child | Head | Position | Subtree Size');
  print('-----|--------|-------|-------------|------|----------|-------------');
  for (int i = 0; i < n; i++) {
    String heavyStr = heavy[i] == -1 ? 'none' : heavy[i].toString();
    print('  ${i.toString().padRight(2)} |   ${parent[i].toString().padRight(4)} |   ${depth[i]}   |     $heavyStr      |  ${head[i]}   |    ${pos[i]}     |      ${subtreeSize[i]}');
  }

  // Print chains
  print('\nHeavy Chains:');
  Map<int, List<int>> chains = {};
  for (int i = 0; i < n; i++) {
    if (!chains.containsKey(head[i])) {
      chains[head[i]] = [];
    }
    chains[head[i]]!.add(i);
  }

  for (var entry in chains.entries) {
    print('Chain starting at ${entry.key}: ${entry.value}');
  }

  // Test LCA queries
  print('\nLCA Queries:');
  List<List<int>> testQueries = [
    [7, 9],
    [3, 8],
    [5, 6],
    [1, 5],
    [7, 6]
  ];

  for (var query in testQueries) {
    int lca = findLCA(query[0], query[1]);
    print('LCA(${query[0]}, ${query[1]}) = $lca');
  }

  // Test path queries
  print('\nPath Decomposition:');
  for (var query in testQueries) {
    var segments = queryPath(query[0], query[1]);
    print('Path from ${query[0]} to ${query[1]}:');
    for (var segment in segments) {
      print('  Segment: position ${segment[0]} to ${segment[1]}');
    }
  }

  // Distance calculation using HLD
  int distance(int u, int v) {
    return depth[u] + depth[v] - 2 * depth[findLCA(u, v)];
  }

  print('\nDistance Queries:');
  for (var query in testQueries) {
    int dist = distance(query[0], query[1]);
    print('Distance(${query[0]}, ${query[1]}) = $dist');
  }

  // Verify HLD properties
  print('\nVerifying HLD Properties:');
  bool valid = true;

  // Check that every node has exactly one head
  for (int i = 0; i < n; i++) {
    if (head[i] < 0 || head[i] >= n) {
      print('Error: Node $i has invalid head ${head[i]}');
      valid = false;
    }
  }

  // Check that heavy edges form chains
  for (int i = 0; i < n; i++) {
    if (heavy[i] != -1) {
      if (head[heavy[i]] != head[i]) {
        print('Error: Heavy edge from $i to ${heavy[i]} doesn\'t maintain chain');
        valid = false;
      }
    }
  }

  // Check position assignment
  Set<int> positions = {};
  for (int i = 0; i < n; i++) {
    if (positions.contains(pos[i])) {
      print('Error: Duplicate position ${pos[i]} for node $i');
      valid = false;
    }
    positions.add(pos[i]);
  }

  if (valid) {
    print('✓ All HLD properties verified successfully!');
  } else {
    print('✗ HLD validation failed!');
  }
}

