void main() {
  // Find all prime numbers up to n
  int n = 100;

  // Create a boolean array and initialize all entries as true
  List<bool> isPrime = List.filled(n + 1, true);
  isPrime[0] = false; // 0 is not prime
  isPrime[1] = false; // 1 is not prime

  // Sieve of Eratosthenes algorithm
  for (int i = 2; i * i <= n; i++) {
    // If isPrime[i] is not changed, then it is a prime
    if (isPrime[i]) {
      // Update all multiples of i
      for (int j = i * i; j <= n; j += i) {
        isPrime[j] = false;
      }
    }
  }

  // Collect all prime numbers
  List<int> primes = [];
  for (int i = 2; i <= n; i++) {
    if (isPrime[i]) {
      primes.add(i);
    }
  }

  // Print results
  print('Prime numbers up to $n:');
  print(primes);
  print('Total count of primes: ${primes.length}');

  // Test primality for specific numbers
  List<int> testNumbers = [17, 24, 29, 35, 47, 50, 73, 91, 97];
  print('\nPrimality test for specific numbers:');
  for (int num in testNumbers) {
    if (num <= n) {
      print('$num is ${isPrime[num] ? "prime" : "not prime"}');
    } else {
      print('$num is outside the range (> $n)');
    }
  }
}

