// A complete Dart program demonstrating sealed classes and pattern matching.

sealed class Shape {}

class Circle extends Shape {
  final double radius;

  Circle(this.radius);
}

class Square extends Shape {
  final double side;

  Square(this.side);
}

class Rectangle extends Shape {
  final double width;
  final double height;

  Rectangle(this.width, this.height);
}

double computeArea(Shape shape) {
  return switch (shape) {
    Circle(radius: var r) => 3.14159 * r * r,
    Square(side: var s) => s * s,
    Rectangle(:var width, :var height) => width * height,
  };
}

