import 'dart:io';

@pragma('vm:entry-point')
void main(List<String> args) {
  // --------------------------------------------------------------------------
  // Simple, self-contained i18n engine ---------------------------------------
  // --------------------------------------------------------------------------

  // 1. Translation catalog: locale → key → phrase
  final Map<String, Map<String, String>> _translations = {
    'en': {
      'app_title': 'Internationalized CLI App',
      'greeting': 'Hello, {name}!',
      'farewell': 'Good-bye!',
      'prompt_name': 'Enter your name: ',
      'unsupported': 'Unsupported locale "{locale}", falling back to English.'
    },
    'es': {
      'app_title': 'Aplicación CLI internacionalizada',
      'greeting': '¡Hola, {name}!',
      'farewell': '¡Adiós!',
      'prompt_name': 'Introduce tu nombre: ',
      'unsupported': 'Idioma "{locale}" no soportado; se usará inglés.'
    },
    'fr': {
      'app_title': 'Application CLI internationalisée',
      'greeting': 'Bonjour, {name} !',
      'farewell': 'Au revoir !',
      'prompt_name': 'Entrez votre nom : ',
      'unsupported': 'Langue « {locale} » non prise en charge ; passage à l\'anglais.'
    },
  };

  const String _fallbackLocale = 'en';

  // 2. Decide which locale to use. Priority: CLI arg → system locale → fallback
  String locale = args.isNotEmpty
      ? args.first.toLowerCase()
      : Platform.localeName.split(RegExp('[-_]')).first.toLowerCase();
  if (!_translations.containsKey(locale)) {
    stderr.writeln(_translations[_fallbackLocale]!['unsupported']!
        .replaceAll('{locale}', locale));
    locale = _fallbackLocale;
  }

  // 3. Translator helper (with simple {placeholder} interpolation)
  String t(String key, [Map<String, String> params = const {}]) {
    final catalog = _translations[locale] ?? _translations[_fallbackLocale]!;
    var phrase = catalog[key] ?? _translations[_fallbackLocale]![key] ?? key;
    for (final entry in params.entries) {
      phrase = phrase.replaceAll('{${entry.key}}', entry.value);
    }
    return phrase;
  }

  // --------------------------------------------------------------------------
  // Demo application ----------------------------------------------------------
  // --------------------------------------------------------------------------

  // User’s name: second CLI arg or ask interactively
  final String name = (args.length > 1)
      ? args[1]
      : () {
          stdout.write(t('prompt_name'));
          return stdin.readLineSync() ?? 'User';
        }();

  stdout
    ..writeln('==== ${t('app_title')} ====')
    ..writeln(t('greeting', {'name': name}))
    ..writeln(t('farewell'));
}

