import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // Hardcoded limit for the sieve (e.g., find all primes up to 100)
  const int limit = 100;

  // Initialize a list of boolean values (true means prime)
  List<bool> isPrime = List<bool>.filled(limit + 1, true);
  isPrime[0] = false;
  isPrime[1] = false;

  // Sieve of Eratosthenes algorithm
  for (int i = 2; i * i <= limit; i++) {
    if (isPrime[i]) {
      // Mark multiples of i as not prime
      for (int j = i * i; j <= limit; j += i) {
        isPrime[j] = false;
      }
    }
  }

  // Collect and print the primes
  List<int> primes = [];
  for (int i = 2; i <= limit; i++) {
    if (isPrime[i]) {
      primes.add(i);
    }
  }

  print('Primes up to $limit: $primes');
}

