// A self-contained Dart script that prints every permutation of a
// given list of integers using classic backtracking.
//
// If the program is run with command-line arguments, those arguments
// are parsed as integers and permuted.  Otherwise the default list
// [1, 2, 3] is used.

@pragma('vm:entry-point')
void main(List<String> args) {
  // Decide which numbers to permute.
  final numbers = args.isNotEmpty
      ? args.map(int.parse).toList()
      : <int>[1, 2, 3];

  // In-place swapping backtracking implementation.
  void backtrack(int start) {
    if (start == numbers.length) {
      print(numbers);
      return;
    }
    for (var i = start; i < numbers.length; i++) {
      // Swap the current element with the element at the 'start' index.
      final tmp = numbers[start];
      numbers[start] = numbers[i];
      numbers[i] = tmp;

      backtrack(start + 1);

      // Swap back to restore the original order before the next iteration.
      numbers[i] = numbers[start];
      numbers[start] = tmp;
    }
