import 'dart:math';

class AVLNode {
  int key;
  AVLNode? left;
  AVLNode? right;
  int height;

  AVLNode(this.key)
      : left = null,
        right = null,
        height = 1;
}

class AVLTree {
  AVLNode? root;

  int _height(AVLNode? node) => node?.height ?? 0;

  int _balance(AVLNode? node) =>
      node == null ? 0 : _height(node.left) - _height(node.right);

  AVLNode _rightRotate(AVLNode y) {
    AVLNode x = y.left!;
    AVLNode T2 = x.right!;

    // Perform rotation
    x.right = y;
    y.left = T2;

    // Update heights
    y.height = max(_height(y.left), _height(y.right)) + 1;
    x.height = max(_height(x.left), _height(x.right)) + 1;

    // Return new root
    return x;
  }

  AVLNode _leftRotate(AVLNode x) {
    AVLNode y = x.right!;
    AVLNode T2 = y.left!;

    // Perform rotation
    y.left = x;
    x.right = T2;

    // Update heights
    x.height = max(_height(x.left), _height(x.right)) + 1;
    y.height = max(_height(y.left), _height(y.right)) + 1;

    // Return new root
    return y;
  }

  AVLNode _insert(AVLNode? node, int key) {
    // 1. Perform normal BST insertion
    if (node == null) {
      return AVLNode(key);
    }

    if (key < node.key) {
      node.left = _insert(node.left, key);
    } else if (key > node.key) {
      node.right = _insert(node.right, key);
    } else {
      // Equal keys not allowed
      return node;
    }

    // 2. Update height
    node.height = 1 + max(_height(node.left), _height(node.right));

    // 3. Get balance factor
    int balance = _balance(node);

    // 4. If unbalanced, then 4 cases

    // Left Left Case
    if (balance > 1 && key < node.left!.key) {
      return _rightRotate(node);
    }

    // Right Right Case
    if (balance < -1 && key > node.right!.key) {
      return _leftRotate(node);
    }

    // Left Right Case
    if (balance > 1 && key > node.left!.key) {
      node.left = _leftRotate(node.left!);
      return _rightRotate(node);
    }

    // Right Left Case
    if (balance < -1 && key < node.right!.key) {
      node.right = _rightRotate(node.right!);
      return _leftRotate(node);
    }

    // Return unchanged node
    return node;
  }

  void insert(int key) {
    root = _insert(root, key);
  }

  void inOrder(AVLNode? node) {
    if (node != null) {
      inOrder(node.left);
      print('${node.key} (h=${node.height})');
      inOrder(node.right);
    }
  }
}

