void main() {
  // Sample array to sort
  List<int> numbers = [64, 34, 25, 12, 22, 11, 90, 88, 45, 50, 43, 24, 9, 5, 77];

  print('Original array: $numbers');

  // Quick sort implementation using nested functions
  void quickSort(List<int> arr, int low, int high) {
    if (low < high) {
      // Partition function
      int partition(List<int> arr, int low, int high) {
        // Choose the rightmost element as pivot
        int pivot = arr[high];

        // Index of smaller element - indicates the right position
        // of pivot found so far
        int i = low - 1;

        for (int j = low; j < high; j++) {
          // If current element is smaller than or equal to pivot
          if (arr[j] <= pivot) {
            i++;
            // Swap elements at i and j
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
          }
        }

        // Swap pivot element with element at i+1
        int temp = arr[i + 1];
        arr[i + 1] = arr[high];
        arr[high] = temp;

        return i + 1;
      }

      // Find partition index
      int partitionIndex = partition(arr, low, high);

      // Recursively sort elements before and after partition
      quickSort(arr, low, partitionIndex - 1);
      quickSort(arr, partitionIndex + 1, high);
    }
  }

  // Call quickSort on the array
  quickSort(numbers, 0, numbers.length - 1);

  print('Sorted array: $numbers');

  // Test with another array including negative numbers
  List<int> moreNumbers = [3, -7, 45, 0, -12, 88, 2, 44, -5, 10];
