@pragma('vm:entry-point')
void main() {
  // Sample array with values in a small range [0-9]
  List<int> arr = [4, 2, 2, 8, 3, 3, 1, 7, 0, 9, 5, 1, 6, 4, 3, 8, 2, 7, 5, 4];

  print('Original array: $arr');

  // Find the range of values
  int minVal = arr.reduce((a, b) => a < b ? a : b);
  int maxVal = arr.reduce((a, b) => a > b ? a : b);
  int range = maxVal - minVal + 1;

  // Create counting array
  List<int> count = List.filled(range, 0);

  // Count occurrences of each element
  for (int i = 0; i < arr.length; i++) {
    count[arr[i] - minVal]++;
  }

  // Modify count array to contain actual positions
  for (int i = 1; i < count.length; i++) {
    count[i] += count[i - 1];
  }

  // Build the output array
  List<int> output = List.filled(arr.length, 0);

  // Build output array by traversing original array from right to left
  // This maintains stability of the sort
  for (int i = arr.length - 1; i >= 0; i--) {
    int element = arr[i];
    int countIndex = element - minVal;
    output[count[countIndex] - 1] = element;
    count[countIndex]--;
  }

  // Copy output array back to original array
  for (int i = 0; i < arr.length; i++) {
    arr[i] = output[i];
  }

  print('Sorted array: $arr');

  // Test with negative numbers
  List<int> arr2 = [-3, 5, -1, 0, 2, -3, 4, 1, -2, 3, 0, -1, 2];
  print('\nOriginal array with negatives: $arr2');

  // Find range for second array
  minVal = arr2.reduce((a, b) => a < b ? a : b);
  maxVal = arr2.reduce((a, b) => a > b ? a : b);
  range = maxVal - minVal + 1;

  // Create counting array for second test
