  // Count occurrences
  for (int i = 0; i < arr2.length; i++) {
    count[arr2[i] - minVal]++;
  }

  // Modify count array to contain actual positions
  for (int i = 1; i < count.length; i++) {
    count[i] += count[i - 1];
  }

  // Build output array
  output = List.filled(arr2.length, 0);

  // Build output array maintaining stability
  for (int i = arr2.length - 1; i >= 0; i--) {
    int element = arr2[i];
    int countIndex = element - minVal;
    output[count[countIndex] - 1] = element;
    count[countIndex]--;
  }

  // Copy back to original
  for (int i = 0; i < arr2.length; i++) {
    arr2[i] = output[i];
  }

  print('Sorted array with negatives: $arr2');

  // Test with single digit range for efficiency demonstration
  List<int> digits = [3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5, 8, 9, 7, 9, 3, 2, 3, 8, 4];
  print('\nOriginal digits array: $digits');

  // Optimized version for known range [0-9]
  count = List.filled(10, 0);

  // Count occurrences
  for (int i = 0; i < digits.length; i++) {
    count[digits[i]]++;
  }

  // Reconstruct array directly from counts (simpler for demonstration)
  int index = 0;
  for (int i = 0; i < 10; i++) {
    while (count[i] > 0) {
      digits[index++] = i;
      count[i]--;
    }
  }

  print('Sorted digits array: $digits');

