  // Define the function to integrate: f(x) = x^2
  double f(double x) => x * x;

  // Integration limits
  double a = 0.0;
  double b = 1.0;

  // Number of Monte Carlo samples
  int n = 1000000;

  // Random number generator
  Random random = Random();

  // Accumulate the sum of f(x_i)
  double sum = 0.0;
  for (int i = 0; i < n; i++) {
    double x = a + (b - a) * random.nextDouble();
    sum += f(x);
  }

  // Approximate the integral
  double integral = (b - a) * sum / n;

  // Exact integral of x^2 from 0 to 1 is 1/3 ≈ 0.333333
  print('Approximate integral: $integral');
  print('Exact integral: ${1.0 / 3.0}');
}

