import 'dart:async';

/// A tiny demo that intercepts uncaught errors and prints a
/// hand-crafted “pretty” stack trace.
///
/// Compile & run:
///   dart run custom_stacktrace.dart
@pragma('vm:entry-point')
void main() {
  // Everything executed in this zone will have its uncaught errors routed
  // through the onError callback where we format the trace ourselves.
  runZonedGuarded(() {
    // --- Any code below will benefit from the custom formatter ---------
    // Purposely trigger an exception so we can see our pretty trace.
    void levelOne() {
      void levelTwo() {
        throw StateError('Something went wrong!');
      }

      levelTwo();
    }

    levelOne();
    // -------------------------------------------------------------------
  }, (Object error, StackTrace stack) {
    // ------------- Custom stack-trace formatting starts here -----------
    final lines = stack.toString().trim().split('\n');

    final buffer = StringBuffer()
      ..writeln('\n=== Custom Stack Trace (top 5 frames) ===')
      ..writeln('Error: $error\n');

    for (var i = 0; i < lines.length && i < 5; i++) {
      final raw = lines[i].trim();

      // Typical Dart line: '#0   Foo.bar (package:my_app/foo.dart:10:3)'
      final match =
          RegExp(r'^#\d+\s+(.+?) \((.+?:\d+:\d+)\)$').firstMatch(raw);

      if (match != null) {
        final function = match.group(1);
        final location = match.group(2);
        buffer.writeln(' • $function  ➜  $location');
      } else {
        // Fallback in case the line doesn't match the expected pattern.
        buffer.writeln(' • $raw');
      }
    }

    if (lines.length > 5) {
      buffer.writeln(' • … (${lines.length - 5} additional frames omitted)');
    }

    buffer.writeln('==========================================\n');
    print(buffer.toString());
    // -------------------------------------------------------------------
  });
}

