  List<List<int>> result1 = [];
  List<int> current1 = [];
  List<bool> used1 = List.filled(nums1.length, false);

  void backtrack1(List<int> nums, List<int> current, List<bool> used, List<List<int>> result) {
    // Base case: if current permutation is complete
    if (current.length == nums.length) {
      result.add(List.from(current));
      return;
    }

    // Try each element that hasn't been used
    for (int i = 0; i < nums.length; i++) {
      if (used[i]) continue;

      // Choose
      current.add(nums[i]);
      used[i] = true;

      // Explore
      backtrack1(nums, current, used, result);

      // Unchoose (backtrack)
      current.removeLast();
      used[i] = false;
    }
  }

  backtrack1(nums1, current1, used1, result1);
  for (var perm in result1) {
    print(perm);
  }

