    if (start == nums.length) {
      result.add(List.from(nums));
      return;
    }

    for (int i = start; i < nums.length; i++) {
      // Swap
      int temp = nums[start];
      nums[start] = nums[i];
      nums[i] = temp;

      // Recurse
      permuteSwap(nums, start + 1, result);

      // Backtrack (swap back)
      temp = nums[start];
