void main() {
  // Coin Change Problem: Find minimum number of coins needed to make a given amount

  // Test case 1: coins = [1, 5, 10, 25], amount = 41
  List<int> coins1 = [1, 5, 10, 25];
  int amount1 = 41;

  // Dynamic Programming approach
  int minCoins(List<int> coins, int amount) {
    if (amount == 0) return 0;

    // dp[i] represents minimum coins needed to make amount i
    List<int> dp = List.filled(amount + 1, amount + 1);
    dp[0] = 0;

    for (int i = 1; i <= amount; i++) {
      for (int coin in coins) {
        if (coin <= i) {
          dp[i] = dp[i] < dp[i - coin] + 1 ? dp[i] : dp[i - coin] + 1;
        }
      }
    }

    return dp[amount] > amount ? -1 : dp[amount];
  }

