import 'dart:io';

// A simple console-based simulation of gesture-based navigation.
// We simulate gestures via text input: 'left' for swipe left, 'right' for swipe right, 'up' for swipe up, 'down' for swipe down, 'exit' to quit.
// Navigation is between virtual "pages" numbered 1 to 5.

@pragma('vm:entry-point')
void main() {
  // Initial state
  int currentPage = 1;
  final int totalPages = 5;

  print('Gesture-based Navigation Simulator');
  print('Enter gestures: left, right, up, down, or exit.');

  while (true) {
    print('\nCurrent Page: $currentPage');

    // Read user input for simulated gesture
    String? input = stdin.readLineSync()?.trim().toLowerCase();

    if (input == 'exit') {
      print('Exiting navigation.');
      break;
    } else if (input == 'left' || input == 'right') {
      // Horizontal navigation: left decreases page, right increases
      if (input == 'left' && currentPage > 1) {
        currentPage--;
        print('Swiped left to page $currentPage');
      } else if (input == 'right' && currentPage < totalPages) {
        currentPage++;
        print('Swiped right to page $currentPage');
      } else {
        print('Cannot swipe $input further.');
      }
    } else if (input == 'up' || input == 'down') {
      // Vertical navigation: up/down could simulate scrolling or jumping
      if (input == 'up') {
        currentPage = 1; // Jump to first page
        print('Swiped up to first page');
      } else if (input == 'down') {
        currentPage = totalPages; // Jump to last page
        print('Swiped down to last page');
      }
    } else {
      print('Invalid gesture. Try left, right, up, down, or exit.');
    }
  }
}

