  // Simple demonstration of arbitrary-precision arithmetic using built-in BigInt.

  // Read two big integers from stdin
  print('Enter the first big integer:');
  String? input1 = stdin.readLineSync();
  print('Enter the second big integer:');
  String? input2 = stdin.readLineSync();

  if (input1 == null || input2 == null) {
    print('Invalid input.');
    return;
  }

  // Parse inputs to BigInt
  BigInt a;
  BigInt b;
  try {
    a = BigInt.parse(input1.trim());
    b = BigInt.parse(input2.trim());
  } catch (e) {
    print('Error parsing input: $e');
    return;
  }

  // Perform various operations
  BigInt sum = a + b;
  BigInt diff = a - b;
  BigInt prod = a * b;
  BigInt? quot;
  BigInt? rem;
  if (b != BigInt.zero) {
    quot = a ~/ b;
    rem = a.remainder(b);
  }

  print('\nResults:');
  print('a + b = $sum');
  print('a - b = $diff');
  print('a * b = $prod');
  if (b != BigInt.zero) {
    print('a ~/ b = $quot');
    print('a % b = $rem');
  } else {
    print('Division by zero is not allowed.');
  }

  // Exponentiation (to a small power)
  print('\nEnter a small integer exponent (e.g. 2 or 10):');
  String? expInput = stdin.readLineSync();
  if (expInput != null) {
    int exp;
    try {
      exp = int.parse(expInput.trim());
      BigInt powResult = a.pow(exp);
      print('a ^ $exp = $powResult');
    } catch (e) {
      print('Invalid exponent.');
    }
  }
}

