  // Example input
  String s = "leetcode";
  List<String> wordDict = ["leet", "code"];

  // Word Break function
  bool wordBreak(String s, List<String> wordDict) {
    Set<String> wordSet = wordDict.toSet();
    List<bool> dp = List.filled(s.length + 1, false);
    dp[0] = true;

    for (int i = 1; i <= s.length; i++) {
      for (int j = 0; j < i; j++) {
        if (dp[j] && wordSet.contains(s.substring(j, i))) {
          dp[i] = true;
          break;
        }
      }
    }
    return dp[s.length];
  }

  // Run and print result
  bool result = wordBreak(s, wordDict);
  print("Can the string '$s' be segmented? $result");

  // Additional test cases
  print(wordBreak("applepenapple", ["apple", "pen"])); // true
  print(wordBreak("catsandog", ["cats", "dog", "sand", "and", "cat"])); // false
}

