  // Sample data: x and y values
  List<double> x = [1, 2, 3, 4, 5];
  List<double> y = [2, 4, 6, 8, 10];

  int n = x.length;

  // Calculate sums
  double sumX = 0;
  double sumY = 0;
  double sumXY = 0;
  double sumX2 = 0;

  for (int i = 0; i < n; i++) {
    sumX += x[i];
    sumY += y[i];
    sumXY += x[i] * y[i];
    sumX2 += x[i] * x[i];
  }

  // Calculate slope (m) and intercept (b)
  double m = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
  double b = (sumY - m * sumX) / n;

  // Print the results
  print('Linear Regression Results:');
  print('Slope (m): $m');
  print('Intercept (b): $b');
  print('Equation: y = ${m.toStringAsFixed(2)}x + ${b.toStringAsFixed(2)}');

  // Example prediction for x = 6
  double prediction = m * 6 + b;
  print('Prediction for x=6: $prediction');
}

