import 'dart:collection';

@pragma('vm:entry-point')
void main() {
  // Example graph as adjacency list (undirected)
  // 0--1
  // |  |
  // 3--2
  // Euler circuit exists (all degrees even)
  Map<int, List<int>> graph = {
    0: [1, 3],
    1: [0, 2],
    2: [1, 3],
    3: [0, 2],
  };

  // Utility to check degree of each vertex
  List<int> degrees(Map<int, List<int>> g) =>
      g.keys.map((v) => g[v]!.length).toList();

  // Check if all non-zero degree vertices are connected
  bool isConnected(Map<int, List<int>> g) {
    Set<int> visited = {};
    // Find a vertex with non-zero degree
    int? start;
    for (var v in g.keys) {
      if (g[v]!.isNotEmpty) {
        start = v;
        break;
      }
    }
    if (start == null) return true; // No edges
    Queue<int> q = Queue()..add(start);
    visited.add(start);
    while (q.isNotEmpty) {
      int u = q.removeFirst();
      for (var v in g[u]!) {
        if (!visited.contains(v)) {
          visited.add(v);
          q.add(v);
        }
      }
    }
    // Check if all vertices with non-zero degree are visited
    for (var v in g.keys) {
      if (g[v]!.isNotEmpty && !visited.contains(v)) return false;
    }
    return true;
  }

  // Check for Eulerian Path or Circuit
  String eulerType(Map<int, List<int>> g) {
    if (!isConnected(g)) return "Graph is not connected";
    int odd = degrees(g).where((d) => d % 2 != 0).length;
    if (odd == 0) return "Eulerian Circuit";
    if (odd == 2) return "Eulerian Path";
    return "Neither Eulerian Path nor Circuit";
  }

  // Find Eulerian Path or Circuit using Hierholzer's Algorithm
  List<int> findEulerian(Map<int, List<int>> g) {
    // Make a deep copy so we can remove edges
    Map<int, List<int>> graphCopy = {};
    for (var v in g.keys) {
      graphCopy[v] = List<int>.from(g[v]!);
    }

    // Find start vertex
    int start = g.keys.first;
    int oddCount = 0;
    for (var v in g.keys) {
      if (g[v]!.length % 2 != 0) {
        start = v;
        oddCount++;
      }
    }
    if (oddCount != 0 && oddCount != 2 && oddCount != 0) {
      return [];
    }

    List<int> path = [];
    void dfs(int u) {
      while (graphCopy[u]!.isNotEmpty) {
        int v = graphCopy[u]!.removeLast();
        graphCopy[v]!.remove(u); // Remove edge both ways
        dfs(v);
      }
      path.add(u);
    }

    dfs(start);
    // If all edges are used, path is valid
    for (var v in graphCopy.keys) {
      if (graphCopy[v]!.isNotEmpty) return [];
    }
    return path.reversed.toList();
  }

  print("Graph: $graph");
  print("Degrees: ${degrees(graph)}");
  String type = eulerType(graph);
  print("Eulerian Type: $type");

  if (type == "Eulerian Circuit" || type == "Eulerian Path") {
    List<int> path = findEulerian(graph);
    if (path.isEmpty) {
      print("No Eulerian path/circuit found.");
    } else {
      print(
          "${type == 'Eulerian Circuit' ? 'Eulerian Circuit' : 'Eulerian Path'}: $path");
    }
  } else {
    print("No Eulerian path or circuit exists.");
  }

  // Try a graph with Eulerian Path (two vertices of odd degree)
  Map<int, List<int>> g2 = {
    0: [1],
    1: [0, 2],
    2: [1, 3],
    3: [2],
  };
  print("\nGraph: $g2");
  print("Degrees: ${degrees(g2)}");
  String type2 = eulerType(g2);
  print("Eulerian Type: $type2");
  if (type2 == "Eulerian Circuit" || type2 == "Eulerian Path") {
    List<int> path2 = findEulerian(g2);
    if (path2.isEmpty) {
      print("No Eulerian path/circuit found.");
    } else {
      print(
          "${type2 == 'Eulerian Circuit' ? 'Eulerian Circuit' : 'Eulerian Path'}: $path2");
    }
  } else {
    print("No Eulerian path or circuit exists.");
  }
}

