void main() {
  // Size of the reservoir
  const int k = 5;
  // Total number of items in the stream
  const int n = 100;

  final List<int> reservoir = <int>[];
  final Random random = Random();

  for (int i = 1; i <= n; i++) {
    if (reservoir.length < k) {
      // Fill the reservoir with the first k items
      reservoir.add(i);
    } else {
      // Replace an element with probability k/i
      int j = random.nextInt(i);
      if (j < k) {
        reservoir[j] = i;
      }
    }
  }

  print('Reservoir sample of size $k from 1..$n: $reservoir');
}
```

