  @Description('First day of the week')
  monday,

  @Description('Second day of the week')
  tuesday,

  @Description('Third day of the week')
  wednesday,

  @Description('Fourth day of the week')
  thursday,

  @Description('Fifth day of the week')
  friday,

  @Description('Sixth day of the week')
  saturday,

  @Description('Seventh day of the week')
  sunday,
}

@pragma('vm:entry-point')
void main() {
  // Print enum annotation
  final enumMirror = Weekday;
  final enumDescription = _getEnumDescription(enumMirror);
  print('Enum annotation: $enumDescription\n');

  // Print value annotations
  for (var value in Weekday.values) {
    final annotation = _getEnumValueDescription(value);
    print('${value.name}: $annotation');
  }
}

/// Helper to get the Description annotation from the enum type.
String? _getEnumDescription(Type enumType) {
  // Since Dart doesn't support reflection in all environments,
  // this works only in VM or with dart:mirrors.
  // Here, we use a manual approach for demonstration.
  if (enumType == Weekday) {
    return (Weekday).toString().contains('Weekday')
        ? 'Represents the days of the week'
        : null;
  }
  return null;
}

/// Helper to get the Description annotation from the enum value.
String? _getEnumValueDescription(Weekday value) {
  switch (value) {
    case Weekday.monday:
      return 'First day of the week';
    case Weekday.tuesday:
      return 'Second day of the week';
    case Weekday.wednesday:
      return 'Third day of the week';
    case Weekday.thursday:
      return 'Fourth day of the week';
    case Weekday.friday:
      return 'Fifth day of the week';
    case Weekday.saturday:
      return 'Sixth day of the week';
    case Weekday.sunday:
      return 'Seventh day of the week';
  }
}

