  // LZW Compression function
  List<int> compress(String uncompressed) {
    // Build the dictionary with ASCII characters
    Map<String, int> dictionary = {};
    for (int i = 0; i < 256; i++) {
      dictionary[String.fromCharCode(i)] = i;
    }

    String w = '';
    List<int> result = [];
    for (String c in uncompressed.split('')) {
      String wc = w + c;
      if (dictionary.containsKey(wc)) {
        w = wc;
