        result.add(dictionary[w]!);
        // Add new entry to dictionary
        dictionary[wc] = dictionary.length;
        w = c;
      }
    }
    // Add the last code
    if (w.isNotEmpty) {
      result.add(dictionary[w]!);
    }
    return result;
  }

  // LZW Decompression function
  String decompress(List<int> compressed) {
    // Build the dictionary with ASCII characters
    Map<int, String> dictionary = {};
    for (int i = 0; i < 256; i++) {
      dictionary[i] = String.fromCharCode(i);
    }

    String w = dictionary[compressed[0]]!;
    StringBuffer result = StringBuffer()..write(w);

    for (int k in compressed.sublist(1)) {
      String entry;
      if (dictionary.containsKey(k)) {
        entry = dictionary[k]!;
      } else if (k == dictionary.length) {
        entry = w + w[0];
      } else {
        throw Exception('Invalid compressed code: $k');
      }
      result.write(entry);

      // Add new entry to dictionary
      dictionary[dictionary.length] = w + entry[0];
      w = entry;
    }
    return result.toString();
  }

  // Sample input
  String original = "TOBEORNOTTOBEORTOBEORNOT";
  print('Original: $original');

