import 'dart:math';

@pragma('vm:entry-point')
void main() {
  final rng = Random();

  // Example data.
  final list = List<int>.generate(10, (i) => i + 1);
  print('Original: $list');

  // Fisher–Yates shuffle.
  for (int i = list.length - 1; i > 0; i--) {
    final j = rng.nextInt(i + 1); // 0 ≤ j ≤ i
    final tmp = list[i];
    list[i] = list[j];
    list[j] = tmp;
  }

  print('Shuffled: $list');
}

