  // Create an instance of the NotificationsCenter.
  final center = NotificationsCenter();

  // Simulate adding some notifications.
  center.addNotification('Welcome to the app!');
  center.addNotification('You have a new message.');
  center.addNotification('Update available.');

  // Display all notifications.
  center.displayAllNotifications();

  // Display unread notifications.
  center.displayUnreadNotifications();

  // Mark some as read.
  center.markAsRead(1);
  center.markAsRead(3); // This exists.
  center.markAsRead(4); // This doesn't exist.

  // Display again after marking.
  center.displayUnreadNotifications();

  // Add one more notification.
  center.addNotification('Battery low.');

  // Final display.
  center.displayAllNotifications();
}

