void main(List<String> args) {
  // If the user supplies command-line arguments they are used as the set,
  // otherwise the default set [1, 2, 3] is used.
  final List<int> set =
      (args.isEmpty ? ['1', '2', '3'] : args).map(int.parse).toList();

  final List<List<int>> subsets = <List<int>>[];

  // Recursive depth-first subset generator.
  void generate(int index, List<int> current) {
    if (index == set.length) {
      subsets.add(List<int>.from(current));
      return;
    }
    // Exclude the current element.
    generate(index + 1, current);

    // Include the current element.
    current.add(set[index]);
    generate(index + 1, current);
    current.removeLast();
  }

  generate(0, <int>[]);

  // Optional: sort subsets by length and then lexicographically for readability.
  subsets.sort((a, b) {
    if (a.length != b.length) return a.length - b.length;
    for (var i = 0; i < a.length; ++i) {
      if (a[i] != b[i]) return a[i] - b[i];
    }
    return 0;
  });

  // Print each subset on its own line.
  for (final subset in subsets) {
    stdout.writeln(subset);
  }
}

