void main(List<String> args) {
  // Parse command-line arguments or use default set [1, 2, 3]
  final List<int> set =
      (args.isEmpty ? ['1', '2', '3'] : args).map(int.parse).toList();

  // List to store all subsets
  final List<List<int>> subsets = <List<int>>[];

  // Recursive function to generate subsets
  void generate(int index, List<int> current) {
    if (index == set.length) {
      // Base case: add a copy of the current subset
      subsets.add(List<int>.from(current));
      return;
    }
    // Exclude the current element
    generate(index + 1, current);

    // Include the current element
    current.add(set[index]);
    generate(index + 1, current);
    // Backtrack: remove the last element to revert changes
    current.removeLast();
  }

  // Start generation with empty current list and index 0
  generate(0, <int>[]);

  // Optional: sort subsets by length and then lexicographically
  subsets.sort((a, b) {
    if (a.length != b.length) {
      return a.length.compareTo(b.length);
    }
    // Lexicographical comparison for subsets of same length
    for (int i = 0; i < a.length; i++) {
      if (a[i] != b[i]) {
        return a[i].compareTo(b[i]);
      }
    }
    return 0; // subsets are equal
  });

  // The subsets list now contains all subsets, sorted (optional)
  // For output or further use, you can print or return subsets here
  // print(subsets); // Uncomment to print the result
}
