  // Validate board size.
  if (n <= 0) {
    print('Board size must be positive.');
    return;
  }

  // Board state: index represents row, value represents column where a queen is placed.
  // Initialize with -1 indicating no queen placed yet.
  final positions = List<int>.filled(n, -1);
  int solutions = 0;

  // Helper function to check if placing a queen at (row, col) is safe.
  bool isSafe(int row, int col) {
    for (int r = 0; r < row; r++) {
      final c = positions[r];
      // Check for same column or same diagonal (absolute differences equal).
      if (c == col || (r - row).abs() == (c - col).abs()) {
        return false;
      }
    }
    return true;
  }

  // Recursive function to place queens using depth-first search.
  void place(int row) {
    if (row == n) {
      // Found a valid solution: increment count and print the board.
      solutions++;
      print('Solution #$solutions');
      for (int r = 0; r < n; r++) {
        // Generate a string for each row: 'Q' for queen, '.' for empty.
