// A self-contained Dart script that computes Fibonacci numbers using memoization.
// Compile and run with:  dart run fibonacci.dart [n]
// If n is omitted, the script prints the series up to n = 10.

import 'dart:io';

@pragma('vm:entry-point') // Prevents the VM from tree-shaking away `main`.
void main(List<String> args) {
  // Parse the first CLI argument; default to 10 if none or invalid.
  final int n = args.isNotEmpty ? int.tryParse(args.first) ?? 10 : 10;

  // Simple in-function memoization map. Pre-seed with base cases.
  final Map<int, int> memo = {0: 0, 1: 1};

  int fib(int k) {
    if (memo.containsKey(k)) return memo[k]!; // Fast path.
    // Recursively compute and memoize the result.
    memo[k] = fib(k - 1) + fib(k - 2);
    return memo[k]!;
  }

  // Print the Fibonacci sequence from 0 to n.
  for (int i = 0; i <= n; i++) {
    stdout.writeln('fib($i) = ${fib(i)}');
  }
}

