import 'dart:core';

abstract class Shape {
  // Factory constructor that returns different subclasses based on type.
  factory Shape(String type, double dimension) {
    if (type == 'circle') {
      return Circle(dimension);
    } else if (type == 'square') {
      return Square(dimension);
    } else {
      throw ArgumentError('Unknown shape type: $type');
    }
  }

  double get area;
}

class Circle implements Shape {
  final double radius;
  Circle(this.radius);

  @override
  double get area => 3.14159 * radius * radius;
}

class Square implements Shape {
  final double side;
  Square(this.side);

  @override
  double get area => side * side;
}

@pragma('vm:entry-point')
