  print('Circle area (radius 5): ${circle.area}');

  // Using the factory constructor to create a Square
  Shape square = Shape('square', 4);
  print('Square area (side 4): ${square.area}');

  // Attempting to create an unsupported shape
  try {
    Shape unknown = Shape('triangle', 3);
    print('This will not be printed: area = ${unknown.area}');
  } catch (e) {
    print('Error: $e');
  }
}

