@pragma('vm:entry-point')
void main() {
  // Fenwick Tree (Binary Indexed Tree) implementation in Dart

  // Sample data (1-based indexing for Fenwick Tree)
  List<int> data = [3, 2, -1, 6, 5, 4, -3, 3, 7, 2, 3];
  int n = data.length;

  // Internal tree array: size n+1, index 0 unused
  List<int> tree = List.filled(n + 1, 0);

  // Least significant bit
  int lsb(int x) => x & -x;

  // Add 'delta' to element at position idx
  void update(int idx, int delta) {
    while (idx <= n) {
      tree[idx] += delta;
      idx += lsb(idx);
    }
  }

  // Sum of elements from 1 to idx
  int prefixSum(int idx) {
    int result = 0;
    while (idx > 0) {
      result += tree[idx];
      idx -= lsb(idx);
    }
    return result;
  }

  // Build the Fenwick Tree in O(n log n)
  for (int i = 0; i < n; i++) {
    update(i + 1, data[i]);
  }

  // Demonstration
  print('Initial data: $data');
  print('Sum of first 5 elements: ${prefixSum(5)}');              // 3+2-1+6+5 = 15
  print('Sum of range 3 to 7: ${prefixSum(7) - prefixSum(2)}');   // elements 3..7

  // Example update: add 4 to the 3rd element
  update(3, 4);
  data[2] += 4;

  print('\nAfter adding 4 to index 3:');
  print('Updated data: $data');
  print('Sum of first 5 elements: ${prefixSum(5)}');              // now 19
  print('Sum of range 3 to 7: ${prefixSum(7) - prefixSum(2)}');
}

