  print('Push-to-Talk Voice Messaging Simulator');
  print('Instructions:');
  print(' - Press Enter to start recording (simulate pushing the button).');
  print(' - Press Enter again to stop recording and send (simulate releasing the button).');
  print(' - Type "exit" and press Enter to quit.');
  print('Note: This is a simulation; no actual audio is recorded.');

  while (true) {
    // Wait for user to start recording
    stdout.write('Press Enter to start recording... ');
    String? input = stdin.readLineSync();
    if (input == null || input.trim().toLowerCase() == 'exit') {
      print('Exiting...');
      break;
    }

    // Simulate starting recording
    DateTime startTime = DateTime.now();
    print('Recording started... Press Enter to stop and send.');

    // Wait for user to stop recording
