// A complete Dart program implementing complex numbers from scratch.

class Complex {
  final double real;
  final double imag;

  Complex(this.real, this.imag);

  // Addition of two complex numbers
  Complex add(Complex other) {
    return Complex(real + other.real, imag + other.imag);
  }

  // Subtraction of two complex numbers
  Complex subtract(Complex other) {
    return Complex(real - other.real, imag - other.imag);
  }

  // Multiplication of two complex numbers
  Complex multiply(Complex other) {
    double newReal = real * other.real - imag * other.imag;
    double newImag = real * other.imag + imag * other.real;
    return Complex(newReal, newImag);
  }

  // Division of two complex numbers
  Complex divide(Complex other) {
    double denominator = other.real * other.real + other.imag * other.imag;
    if (denominator == 0) {
      throw ArgumentError('Division by zero');
    }
    double newReal = (real * other.real + imag * other.imag) / denominator;
    double newImag = (imag * other.real - real * other.imag) / denominator;
    return Complex(newReal, newImag);
  }

  // Magnitude (absolute value)
  double magnitude() {
    return real * real + imag * imag;
  }

  @override
  String toString() {
    if (imag == 0) return '$real';
    if (real == 0) return '${imag}i';
    return imag > 0 ? '$real + ${imag}i' : '$real - ${-imag}i';
  }
}

