  Random random = Random();

  for (int i = shuffled.length - 1; i > 0; i--) {
    // Generate random index from 0 to i (inclusive)
    int j = random.nextInt(i + 1);

    // Swap elements at positions i and j
    int temp = shuffled[i];
    shuffled[i] = shuffled[j];
    shuffled[j] = temp;
  }

  print('Shuffled list: $shuffled');

  // Demonstrate multiple shuffles to show randomness
  print('\nMultiple shuffles of the same list:');
  for (int round = 1; round <= 5; round++) {
    List<int> testList = List.from(numbers);

    // Shuffle again
    for (int i = testList.length - 1; i > 0; i--) {
      int j = random.nextInt(i + 1);
      int temp = testList[i];
      testList[i] = testList[j];
      testList[j] = temp;
