// Example: Implicit interfaces in Dart.
//
// Every class in Dart defines an implicit interface.  A class can
// “implement” any number of these interfaces and must then provide
// concrete definitions for all the members it inherits.

class MessagePrinter {
  void printMessage(String message) => print('MessagePrinter: $message');
}

class TimestampProvider {
  String timestamp() => DateTime.now().toIso8601String();
}

// Logger implements the *implicit* interfaces of MessagePrinter
// and TimestampProvider.
class Logger implements MessagePrinter, TimestampProvider {
  @override
  void printMessage(String message) {
    print('[${timestamp()}] $message');
  }

  @override
  String timestamp() => DateTime.now().toIso8601String();
}

@pragma('vm:entry-point') // Prevents the entry-point from being tree-shaken.
void main() {
  // Logger can be viewed through any of the interfaces it implements.
  Logger fullLogger          = Logger();
  MessagePrinter asPrinter   = fullLogger;
  TimestampProvider asTime   = fullLogger;

  asPrinter.printMessage('Hello, implicit interfaces!');
  print('Direct timestamp: ${asTime.timestamp()}');

  // Polymorphism with a list of interface types.
  List<MessagePrinter> printers = [Logger(), Logger(), Logger()];
  for (var i = 0; i < printers.length; i++) {
    printers[i].printMessage('Item $i in a polymorphic list');
  }
}

