@pragma('vm:entry-point')
void main(List<String> args) {
  // Expect exactly two command-line arguments: base and exponent.
  if (args.length != 2) {
    print('Usage: dart fast_exp.dart <base> <exponent>');
    print('Example: dart fast_exp.dart 5 13  ➜  5^13 = 1220703125');
    return;
  }

  // Parse the base as BigInt (arbitrary precision) and the exponent as int.
  //   • BigInt lets the program handle very large results without overflow.
  //   • The exponent is kept as int because only its bits are inspected.
  final BigInt base = BigInt.parse(args[0]);
  int exponent = int.parse(args[1]);

  if (exponent < 0) {
    print('Exponent must be non-negative.');
    return;
  }

  BigInt result = BigInt.one; // Accumulates the answer.
  BigInt power  = base;       // Current power of base being considered.

  // Iterative binary (fast) exponentiation.
  // O(log exponent) time and O(1) extra space.
  while (exponent > 0) {
    if ((exponent & 1) == 1) {
      result *= power;        // Multiply the current power into the result.
    }
    power *= power;           // Square the base for the next bit.
    exponent >>= 1;           // Shift to examine the next bit.
  }

  print('${args[0]}^${args[1]} = $result');
}

