void main() {
  // Sample array to sort
  List<int> arr = [170, 45, 75, 90, 802, 24, 2, 66];

  // Find the maximum number to know the number of digits
  int maxVal = arr.isEmpty ? 0 : arr.reduce((a, b) => a > b ? a : b);

  // Perform counting sort for every digit exponent (1, 10, 100, ...)
  for (int exp = 1; maxVal ~/ exp > 0; exp *= 10) {
    // Output array that will have sorted arr by current digit
    List<int> output = List.filled(arr.length, 0);
    // Count array to store count of occurrences for digits 0-9
    List<int> count = List.filled(10, 0);

    // Store count of occurrences in count[]
    for (int i = 0; i < arr.length; i++) {
      int digit = (arr[i] ~/ exp) % 10;
      count[digit]++;
    }

    // Change count[i] so that count[i] contains actual
    // position of this digit in output[]
    for (int i = 1; i < 10; i++) {
      count[i] += count[i - 1];
    }

    // Build the output array
    for (int i = arr.length - 1; i >= 0; i--) {
      int digit = (arr[i] ~/ exp) % 10;
      output[count[digit] - 1] = arr[i];
      count[digit]--;
    }

    // Copy the output array to arr[], so that arr[] now
    // contains sorted numbers according to current digit
    for (int i = 0; i < arr.length; i++) {
      arr[i] = output[i];
    }
  }

  // Print the sorted array
  print('Sorted array: $arr');
}

