    highlightPadding: 0.0,
  ));

  // Start the tutorial
  print('Starting in-app tutorial...\n');
  tutorialSystem.start();

  // Simulate user interactions
  Timer.periodic(Duration(seconds: 2), (timer) {
    if (tutorialSystem.isActive) {
      tutorialSystem.next();
    } else {
      timer.cancel();
      print('\nTutorial completed!');

      // Show tutorial analytics
      print('\nTutorial Analytics:');
      tutorialSystem.getAnalytics().forEach((key, value) {
        print('  $key: $value');
      });
    }
  });

  // Keep the program running
  Timer(Duration(seconds: 12), () {
    print('\nProgram finished.');
  });
}

enum OverlayPosition { top, bottom, left, right, center }

class TutorialStep {
  final String id;
  final String title;
  final String description;
  final String? targetElement;
  final OverlayPosition position;
  final double highlightPadding;

  TutorialStep({
    required this.id,
    required this.title,
    required this.description,
    this.targetElement,
    required this.position,
    required this.highlightPadding,
  });
}

class TutorialSystem {
  final List<TutorialStep> _steps = [];
  int _currentStepIndex = -1;
  bool _isActive = false;
  final Map<String, dynamic> _analytics = {
    'startTime': null,
    'endTime': null,
    'stepsCompleted': 0,
    'totalSteps': 0,
    'skipped': false,
  };

  bool get isActive => _isActive;

  void addStep(TutorialStep step) {
    _steps.add(step);
    _analytics['totalSteps'] = _steps.length;
  }

  void start() {
    if (_steps.isEmpty) {
      print('No tutorial steps defined.');
      return;
    }

    _isActive = true;
    _currentStepIndex = 0;
    _analytics['startTime'] = DateTime.now();
    _showCurrentStep();
  }

  void next() {
    if (!_isActive) return;

    _currentStepIndex++;
    _analytics['stepsCompleted'] = _currentStepIndex;

    if (_currentStepIndex >= _steps.length) {
      _complete();
    } else {
      _showCurrentStep();
    }
  }

  void previous() {
    if (!_isActive || _currentStepIndex <= 0) return;

    _currentStepIndex--;
    _showCurrentStep();
  }

  void skip() {
    if (!_isActive) return;

    _analytics['skipped'] = true;
    _complete();
  }

  void _complete() {
    _isActive = false;
    _analytics['endTime'] = DateTime.now();
    _hideOverlay();
    print('\n✓ Tutorial finished!');
  }

  void _showCurrentStep() {
    if (_currentStepIndex < 0 || _currentStepIndex >= _steps.length) return;

    final step = _steps[_currentStepIndex];
    _renderOverlay(step);
  }

  void _renderOverlay(TutorialStep step) {
    print('\n' + '=' * 50);
    print('Step ${_currentStepIndex + 1} of ${_steps.length}');
    print('=' * 50);

    // Simulate overlay rendering
    if (step.targetElement != null) {
      print('🎯 Highlighting: ${step.targetElement}');
      print('📍 Position: ${step.position.toString().split('.').last}');
      print('📏 Padding: ${step.highlightPadding}px');

      // Simulate highlight box
      _drawHighlightBox(step.targetElement!, step.highlightPadding);
    }

    // Show tooltip
    _drawTooltip(step.title, step.description, step.position);

    // Show navigation
    print('\n[Previous] [Next] [Skip]');
  }

  void _drawHighlightBox(String element, double padding) {
    print('\n┌' + '─' * 30 + '┐');
    print('│ ' + element.padRight(28) + ' │');
    print('│ ' + '(highlighted area)'.padRight(28) + ' │');
    print('└' + '─' * 30 + '┘');
  }

  void _drawTooltip(String title, String description, OverlayPosition position) {
    final arrow = _getArrow(position);

    print('\n$arrow');
    print('╔' + '═' * 40 + '╗');
    print('║ ' + title.padRight(38) + ' ║');
    print('╟' + '─' * 40 + '╢');

    // Word wrap description
    final words = description.split(' ');
    String line = '';
    for (final word in words) {
      if (line.length + word.length + 1 > 38) {
        print('║ ' + line.padRight(38) + ' ║');
        line = word;
      } else {
        line += (line.isEmpty ? '' : ' ') + word;
      }
    }
    if (line.isNotEmpty) {
      print('║ ' + line.padRight(38) + ' ║');
    }

    print('╚' + '═' * 40 + '╝');
  }

  String _getArrow(OverlayPosition position) {
    switch (position) {
      case OverlayPosition.top:
        return '     ▲';
      case OverlayPosition.bottom:
        return '     ▼';
      case OverlayPosition.left:
        return '◄────';
      case OverlayPosition.right:
        return '────►';
      case OverlayPosition.center:
        return '     ◆';
    }
  }

  void _hideOverlay() {
    print('\n[Overlay hidden]');
  }

  Map<String, dynamic> getAnalytics() {
    if (_analytics['startTime'] != null && _analytics['endTime'] != null) {
      final duration = (_analytics['endTime'] as DateTime)
          .difference(_analytics['startTime'] as DateTime);
      _analytics['duration'] = '${duration.inSeconds} seconds';
    }
    return Map.from(_analytics);
  }
}

