void main(List<String> args) {
  // Backtracking permutations with support for duplicate elements.
  // Usage: dart run script.dart A B C
  // If no args are provided, defaults to [1, 2, 3].

  final List<String> items = args.isNotEmpty ? args : ['1', '2', '3'];

  // Build a frequency map to handle duplicates and maintain insertion order.
  final Map<String, int> counts = <String, int>{};
  final List<String> order = <String>[];
  for (final s in items) {
    if (!counts.containsKey(s)) {
      counts[s] = 1;
      order.add(s);
    } else {
      counts[s] = counts[s]! + 1;
    }
  }

  final int n = items.length;
  final List<String> path = <String>[];
  int total = 0;

  void backtrack() {
    if (path.length == n) {
      print('[${path.join(', ')}]');
      total++;
      return;
    }
    for (final key in order) {
      final int c = counts[key]!;
      if (c == 0) continue;
      counts[key] = c - 1;
      path.add(key);
      backtrack();
      path.removeLast();
      counts[key] = c;
    }
  }

  backtrack();
  print('Total permutations: $total');
}

