  final List<String> searchHistory = [];

  print('=== In-App Search with History ===');
  print('Type your search queries below.');
  print('Commands:');
  print('  /history - Show search history');
  print('  /clear   - Clear search history');
  print('  /exit    - Exit the app');
  print('-----------------------------------');

  while (true) {
    stdout.write('Search> ');
    String? input = stdin.readLineSync();

    if (input == null) {
      print('\nInput error. Exiting.');
      break;
    }

    input = input.trim();

    if (input.isEmpty) continue;

    if (input == '/exit') {
      print('Goodbye!');
      break;
    } else if (input == '/history') {
      if (searchHistory.isEmpty) {
        print('No search history yet.');
      } else {
        print('--- Search History ---');
        for (int i = 0; i < searchHistory.length; i++) {
          print('${i + 1}. ${searchHistory[i]}');
        }
        print('----------------------');
      }
    } else if (input == '/clear') {
      searchHistory.clear();
      print('Search history cleared.');
    } else {
      // Add to history (most recent first, remove duplicates)
      searchHistory.removeWhere((q) => q.toLowerCase() == input!.toLowerCase());
      searchHistory.insert(0, input);

      // Keep only the most recent maxHistory items
      if (searchHistory.length > maxHistory) {
        searchHistory.removeRange(maxHistory, searchHistory.length);
      }

      // Simulate search results
      print('Searching for "$input"...');
      print('Results for "$input": [simulated results]');
    }
  }
}

