  // Simple in-app content-sharing demo running in the console.
  // Users can register, post (“share”) messages to other users,
  // and read their personal inboxes.
  // ---------------------------------------------------------------------------

  // In-memory “database” (username -> inbox list).
  final Map<String, List<Map<String, dynamic>>> inboxes = {};

  // Helper for reading a line of input with a prompt.
  String _read(String prompt) {
    stdout.write(prompt);
    return stdin.readLineSync()!.trim();
  }

  // Local menu actions.
  void _registerUser() {
    final name = _read('Choose a user name: ');
    if (name.isEmpty) {
      print('Name cannot be empty.');
    } else if (inboxes.containsKey(name)) {
      print('User “$name” already exists.');
    } else {
      inboxes[name] = [];
      print('User “$name” registered successfully.');
    }
  }

  void _listUsers() {
    if (inboxes.isEmpty) {
      print('No users registered yet.');
    } else {
      print('Registered users (${inboxes.length}): ${inboxes.keys.join(', ')}');
    }
  }

  void _shareContent() {
    if (inboxes.length < 2) {
      print('At least two users are required to share content.');
      return;
    }

    final from = _read('Sender user name: ');
    if (!inboxes.containsKey(from)) {
      print('Unknown sender "$from".');
      return;
    }

    final to = _read('Recipient user name: ');
    if (!inboxes.containsKey(to)) {
      print('Unknown recipient "$to".');
      return;
    }

    final message = _read('Message to share: ');
    if (message.isEmpty) {
      print('Cannot share an empty message.');
      return;
    }

    final payload = <String, dynamic>{
      'from': from,
      'message': message,
      'timestamp': DateTime.now()
    };
    inboxes[to]!.add(payload);

    print('Message shared from "$from" to "$to".');
  }

  void _viewInbox() {
    final user = _read('User name: ');
    final box = inboxes[user];
    if (box == null) {
      print('Unknown user "$user".');
      return;
    }
    if (box.isEmpty) {
      print('Inbox is empty.');
      return;
    }
    print('---- Inbox of $user ----');
    for (var i = 0; i < box.length; i++) {
      final item = box[i];
      print(
          '${i + 1}) From: ${item['from']}\n   At: ${item['timestamp']}\n   "${item['message']}"\n');
    }
    print('------------------------');
  }

  // Main loop.
  while (true) {
    print('\n=== In-App Content Sharing Demo ===');
    print('1) Register new user');
    print('2) List users');
    print('3) Share content');
    print('4) View inbox');
    print('0) Exit');
    final choice = _read('Select an option: ');

    switch (choice) {
      case '1':
        _registerUser();
        break;
      case '2':
        _listUsers();
        break;
      case '3':
        _shareContent();
        break;
      case '4':
        _viewInbox();
        break;
      case '0':
        print('Good-bye!');
        exit(0);
      default:
        print('Invalid selection.');
    }
  }
}

