void main() {
  // Objective function: Let's use f(x) = x^2 + 4*sin(5*x)
  double objective(double x) => x * x + 4 * sin(5 * x);

  final rand = Random();
  double current = rand.nextDouble() * 10 - 5; // Initial solution in [-5,5]
  double best = current;
  double bestVal = objective(best);

  double temp = 10.0;
  final double tempMin = 1e-4;
  final double alpha = 0.98;
  final int iterPerTemp = 100;

  print('Simulated Annealing to minimize f(x) = x^2 + 4*sin(5x)');
  print('Initial x: $current, f(x): ${objective(current)}');

  while (temp > tempMin) {
    for (int i = 0; i < iterPerTemp; i++) {
      // Generate neighbor: small random step
      double step = (rand.nextDouble() * 2 - 1) * 0.5; // step in [-0.5,0.5]
      double neighbor = current + step;
      // Keep within bounds [-5,5]
      neighbor = neighbor.clamp(-5.0, 5.0);

      double delta = objective(neighbor) - objective(current);

      if (delta < 0 || rand.nextDouble() < exp(-delta / temp)) {
        current = neighbor;
        if (objective(current) < bestVal) {
          best = current;
          bestVal = objective(current);
        }
      }
    }
    temp *= alpha;
  }

  print('Best found x: $best, f(x): $bestVal');
}

