@pragma('vm:entry-point')
void main() {
  // Memoization cache to store computed Fibonacci values
  final Map<int, int> memo = {};

  // Fibonacci function with memoization
  int fibonacci(int n) {
    // Base cases
    if (n <= 0) return 0;
    if (n == 1) return 1;

    // Check if value already computed and cached
    if (memo.containsKey(n)) {
      return memo[n]!;
    }

    // Compute and store in cache
    memo[n] = fibonacci(n - 1) + fibonacci(n - 2);
    return memo[n]!;
  }

  // Test the fibonacci function
  print('Fibonacci sequence with memoization:');
  print('=====================================');

  // Calculate and display first 20 Fibonacci numbers
  for (int i = 0; i <= 20; i++) {
    print('F($i) = ${fibonacci(i)}');
  }

  print('\n--- Larger numbers (demonstrating memoization efficiency) ---');

  // Calculate some larger Fibonacci numbers
  final largeNumbers = [30, 35, 40, 45];
  for (int n in largeNumbers) {
    final startTime = DateTime.now();
    final result = fibonacci(n);
    final endTime = DateTime.now();
    final duration = endTime.difference(startTime).inMicroseconds;
    print('F($n) = $result (computed in $duration microseconds)');
  }

  // Show cache size
  print('\nCache size: ${memo.length} entries');

  // Demonstrate cache effectiveness by recalculating
  print('\n--- Recalculating F(45) with cache ---');
  final startTime = DateTime.now();
  final cachedResult = fibonacci(45);
  final endTime = DateTime.now();
  final duration = endTime.difference(startTime).inMicroseconds;
  print('F(45) = $cachedResult (retrieved in $duration microseconds)');
}

