        print('On the X-axis at x=$x');
        break;

      // Matches points where x == y (the line y = x).
      case (var x, var y) when x == y:
        print('On the line y = x at ($x, $y)');
        break;

      // Default match for all remaining points.
      case (var x, var y):
        print('Point ($x, $y)');
    }
  }

  // Record pattern inside an if-case.
  final person = ('Alice', 32);

  if (person case (String name, int age)) {
    print('$name is $age years old.');
  }
