import 'dart:io';
import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // Simulated analytics data
  int totalUsers = 1000;
  int activeSessions = 150;
  double averageSessionTime = 12.5; // in minutes
  List<int> dailyLogins = [50, 100, 150, 200, 250, 300, 350]; // Last 7 days

  print('Welcome to the In-App Analytics Dashboard!');
  print('This is a console-based simulation.');

  bool running = true;
  while (running) {
    // Display dashboard
    print('\n--- Analytics Dashboard ---');
    print('Total Users: $totalUsers');
    print('Active Sessions: $activeSessions');
    print('Average Session Time: $averageSessionTime minutes');

    // Display a simple ASCII bar chart for daily logins
    print('\nDaily Logins (Last 7 Days):');
    for (int i = 0; i < dailyLogins.length; i++) {
      String bar = '*' * (dailyLogins[i] ~/ 10); // Scale down for console
      print('Day ${i + 1}: $bar (${dailyLogins[i]})');
    }

    // Simulate data update
    totalUsers += Random().nextInt(10);
    activeSessions = Random().nextInt(200) + 100;
    averageSessionTime = 10 + Random().nextDouble() * 5;
    for (int i = 0; i < dailyLogins.length; i++) {
      dailyLogins[i] = max(0, dailyLogins[i] + Random().nextInt(50) - 25);
