  // Radix sort implementation (assumes non-negative integers)
  // Find the maximum number to determine the number of digits
  int max = arr[0];
  for (int i = 1; i < arr.length; i++) {
    if (arr[i] > max) {
      max = arr[i];
    }
  }

  // Perform counting sort for every digit place (exp = 1, 10, 100, ...)
  for (int exp = 1; max ~/ exp > 0; exp *= 10) {
    // Counting sort for the current digit place
    List<int> output = List<int>.filled(arr.length, 0);
    List<int> count = List<int>.filled(10, 0);

    // Store count of occurrences in count[]
    for (int i = 0; i < arr.length; i++) {
      int digit = (arr[i] ~/ exp) % 10;
      count[digit]++;
    }

    // Change count[i] so that count[i] now contains actual position of this digit in output[]
    for (int i = 1; i < 10; i++) {
      count[i] += count[i - 1];
    }

    // Build the output array (traverse from end to maintain stability)
    for (int i = arr.length - 1; i >= 0; i--) {
      int digit = (arr[i] ~/ exp) % 10;
      output[count[digit] - 1] = arr[i];
      count[digit]--;
    }

    // Copy the output array to arr[], so that arr[] now contains sorted numbers according to current digit
    for (int i = 0; i < arr.length; i++) {
      arr[i] = output[i];
    }
  }

