    print('No input detected. Using sample: $data');
  } else {
    // Parse input: trim, split by whitespace, convert to integers.
    data = raw.trim().split(RegExp(r'\s+')).map(int.parse).toList();
  }

  // Check if there's nothing to sort.
  if (data.isEmpty) {
    print('Nothing to sort.');
    return;
  }

  // 1. Find minimum and maximum to size the counting array.
  int minVal = data.reduce((a, b) => a < b ? a : b);
  int maxVal = data.reduce((a, b) => a > b ? a : b);
  int range = maxVal - minVal + 1;

  // 2. Build frequency array.
  List<int> counts = List<int>.filled(range, 0);
  for (var value in data) {
    counts[value - minVal]++;
  }

  // 3. Reconstruct the sorted list in place.
  int index = 0;
  for (int i = 0; i < range; i++) {
    while (counts[i] > 0) {
      data[index] = i + minVal;
      index++;
      counts[i]--;
    }
  }

  // 4. Output the sorted result.
  print('Sorted: $data');
}
```

