     Here we minimise  f(x) = x² + 10·sin(x). */
  double f(double x) => x * x + 10 * sin(x);

  // Simulated-annealing parameters
  double temp = 1000.0;      // initial temperature
  const double tMin = 1e-4;  // stopping temperature
  const double alpha = 0.99; // cooling rate

  // Initial solution (pick a random point in [-10, 10])
  double x = rand.nextDouble() * 20 - 10;
  double energy = f(x);

  // Best-so-far
  double bestX = x;
  double bestEnergy = energy;

  int iter = 0;
  while (temp > tMin) {
    // 1. Generate neighbour: random step scaled by √temp
    final step = (rand.nextDouble() * 2 - 1) * sqrt(temp);
    final candidateX = x + step;
    final candidateEnergy = f(candidateX);

    // 2. Decide whether to accept
    if (candidateEnergy < energy ||
        rand.nextDouble() <
            exp((energy - candidateEnergy) / temp)) {
      x = candidateX;
      energy = candidateEnergy;
    }

    // 3. Keep best found
    if (energy < bestEnergy) {
      bestEnergy = energy;
      bestX = x;
    }

    // 4. Periodic logging
    if (iter % 1000 == 0) {
      print('Iter $iter  |  T=${temp.toStringAsFixed(3)}  '
          '|  best f(x)=${bestEnergy.toStringAsFixed(6)}  '
          '@ x=${bestX.toStringAsFixed(6)}');
    }

    // 5. Cool system
    temp *= alpha;
    iter++;
  }

  print('\nFinished after $iter iterations.');
  print(
      'Best solution: x = ${bestX.toStringAsFixed(6)}, f(x) = ${bestEnergy.toStringAsFixed(6)}');
