// monte_carlo_integration.dart
import 'dart:math';
import 'dart:io';

@pragma('vm:entry-point')
void main(List<String> args) {
  // Integrand and interval: ∫₀^π sin(x) dx = 2
  const double a = 0.0;          // lower bound
  const double b = pi;           // upper bound

  // Number of random samples (default: 1 000 000)
  final int n = (args.isNotEmpty) ? int.tryParse(args[0]) ?? 1000000 : 1000000;
  final Random rng = Random.secure();

  double sum = 0.0;
  double sumSq = 0.0;

  for (int i = 0; i < n; ++i) {
    final double x = a + (b - a) * rng.nextDouble(); // uniform sample in [a, b]
    final double fx = sin(x);
    sum += fx;
    sumSq += fx * fx;
  }

  final double mean = sum / n;
  final double estimate = (b - a) * mean;

  // Standard error of the estimate
  final double variance = (sumSq / n) - mean * mean;
  final double stdErr = (b - a) * sqrt(variance / n);

  stdout
    ..writeln('Monte Carlo estimate of ∫₀^π sin(x) dx')
    ..writeln('Samples: $n')
    ..writeln('Estimate:  $estimate ± $stdErr')
    ..writeln('Exact:     2.0');
}

