import 'dart:io';

@pragma('vm:entry-point')
void main(List<String> args) {
  /*
   * Simple standalone suffix–array builder (O(n log² n) using the doubling
   * algorithm).  Run with:
   *   dart suffix_array.dart "your string"
   * If no argument is supplied the demo uses "banana".
   */

  // 1. Obtain the string to process.
  final String text = args.isNotEmpty ? args.join(' ') : 'banana';
  final int n = text.length;
  if (n == 0) {
    stdout.writeln('Empty input.');
    exit(0);
  }

  // 2. Initialisation.
  final List<int> sa   = List<int>.generate(n, (i) => i);   // suffix array
  final List<int> rank = List<int>.generate(n, (i) => text.codeUnitAt(i));
  final List<int> tmp  = List<int>.filled(n, 0);

  // 3. Doubling loop: k = current length of compared prefix.
  for (int k = 1; k < n; k <<= 1) {
    // Sort based on first rank and second rank (rank at i+k).
    sa.sort((int a, int b) {
      if (rank[a] != rank[b]) return rank[a] - rank[b];
      final int ra = (a + k < n) ? rank[a + k] : -1;
      final int rb = (b + k < n) ? rank[b + k] : -1;
      return ra - rb;
    });

    // Re-assign temporary ranks.
    tmp[sa[0]] = 0;
    for (int i = 1; i < n; i++) {
      final int prev = sa[i - 1], curr = sa[i];
      final bool diffFirst  = rank[prev] != rank[curr];
      final int  prevSecond = (prev + k < n) ? rank[prev + k] : -1;
      final int  currSecond = (curr + k < n) ? rank[curr + k] : -1;
      final bool diffSecond = prevSecond != currSecond;
      tmp[curr] = tmp[prev] + ((diffFirst || diffSecond) ? 1 : 0);
    }

    // Copy back new ranks.
    for (int i = 0; i < n; i++) {
      rank[i] = tmp[i];
    }

    // All ranks unique ⇒ early stop.
    if (rank[sa.last] == n - 1) break;
  }

  // 4. Output result.
  stdout.writeln('Input : "$text"');
  stdout.writeln('Suffix array (index : suffix):');
  for (final idx in sa) {
    stdout.writeln('${idx.toString().padLeft(3)} : ${text.substring(idx)}');
  }
}

