      final int ra = (a + k < n) ? rank[a + k] : -1;
      final int rb = (b + k < n) ? rank[b + k] : -1;
      return ra - rb;
    });

    // Re-assign temporary ranks.
    tmp[sa[0]] = 0;
    for (int i = 1; i < n; i++) {
      final int prev = sa[i - 1];
      final int curr = sa[i];
      final bool diffFirst = rank[prev] != rank[curr];
      final int prevSecond = (prev + k < n) ? rank[prev + k] : -1;
      final int currSecond = (curr + k < n) ? rank[curr + k] : -1;
      final bool diffSecond = prevSecond != currSecond;
      tmp[curr] = tmp[prev] + ((diffFirst || diffSecond) ? 1 : 0);
    }

    // Copy back new ranks.
    for (int i = 0; i < n; i++) {
      rank[i] = tmp[i];
    }

    // All ranks unique ⇒ early stop.
    if (rank[sa.last] == n - 1) break;
  }

  // 4. Output result.
  stdout.writeln('Input : "$text"');
  stdout.writeln('Suffix array (index : suffix):');
  for (final idx in sa) {
    stdout.writeln('${idx.toString().padLeft(3)} : ${text.substring(idx)}');
  }
}
```

