  // Simple in-memory calendar representation (map of dates to events)
  Map<DateTime, List<String>> calendar = {};

  // Function to add an event to the calendar
  void addEvent(DateTime date, String event) {
    final normalizedDate = DateTime(date.year, date.month, date.day);
    if (!calendar.containsKey(normalizedDate)) {
      calendar[normalizedDate] = [];
    }
    calendar[normalizedDate]!.add(event);
    print('Event added: "$event" on ${normalizedDate.toIso8601String().substring(0, 10)}');
  }

  // Function to view events for a specific date
  void viewEvents(DateTime date) {
    final normalizedDate = DateTime(date.year, date.month, date.day);
    if (calendar.containsKey(normalizedDate) && calendar[normalizedDate]!.isNotEmpty) {
      print('Events on ${normalizedDate.toIso8601String().substring(0, 10)}:');
      for (var event in calendar[normalizedDate]!) {
        print('- $event');
      }
    } else {
      print('No events on ${normalizedDate.toIso8601String().substring(0, 10)}');
    }
  }

  // Function to print a simple calendar for the current month
  void printCalendar() {
    final now = DateTime.now();
    final firstDayOfMonth = DateTime(now.year, now.month, 1);
    final lastDayOfMonth = DateTime(now.year, now.month + 1, 0);
    final daysInMonth = lastDayOfMonth.day;

    print('Calendar for ${now.year}-${now.month.toString().padLeft(2, '0')}');
    print('Sun Mon Tue Wed Thu Fri Sat');

    // Calculate starting weekday (0 = Sunday, 6 = Saturday)
    int weekday = firstDayOfMonth.weekday % 7; // Adjust to make Sunday 0
    String line = ' ' * (weekday * 4); // Padding for first week

    for (int day = 1; day <= daysInMonth; day++) {
      line += day.toString().padLeft(3, ' ').padRight(4);
      if ((weekday + day) % 7 == 0 || day == daysInMonth) {
        print(line.trimRight());
        line = '';
      }
    }
  }

  // Main logic: Print calendar, add some events, and view them
  print('Welcome to Simple Calendar Integration Demo');
  printCalendar();

  // Add sample events
  addEvent(DateTime.now(), 'Team Meeting');
  addEvent(DateTime.now().add(Duration(days: 1)), 'Doctor Appointment');
  addEvent(DateTime.now().add(Duration(days: 2)), 'Birthday Party');

  // View events for today and tomorrow
  viewEvents(DateTime.now());
  viewEvents(DateTime.now().add(Duration(days: 1)));

  // Interactive part: Allow user to add an event
  print('\nEnter a date (YYYY-MM-DD) to add an event:');
  String? dateInput = stdin.readLineSync();
  print('Enter event description:');
  String? eventInput = stdin.readLineSync();

  if (dateInput != null && eventInput != null) {
    try {
      DateTime parsedDate = DateTime.parse(dateInput);
      addEvent(parsedDate, eventInput);
      viewEvents(parsedDate);
    } catch (e) {
      print('Invalid date format. Please use YYYY-MM-DD.');
    }
  }

  print('Calendar integration demo complete.');
}

