void main() {
  // Example input string
  String s = "banana";

  // Append a terminal character smaller than any other character
  s += "\$";

  int n = s.length;
  List<int> sa = List.filled(n, 0); // Suffix array
  List<int> rank = List.filled(n, 0);
  List<int> tmp = List.filled(n, 0);

  // Initial ranking by single character
  for (int i = 0; i < n; i++) {
    sa[i] = i;
    rank[i] = s.codeUnitAt(i);
  }

  for (int k = 1; k < n; k <<= 1) {
    // Comparator for current k
    int compare(int i, int j) {
      if (rank[i] != rank[j]) return rank[i] - rank[j];
      int ri = (i + k < n) ? rank[i + k] : -1;
      int rj = (j + k < n) ? rank[j + k] : -1;
      return ri - rj;
    }

    // Sort sa by 2k-length substrings
    sa.sort(compare);

    // Temporary array for new ranks
    tmp[sa[0]] = 0;
    for (int i = 1; i < n; i++) {
      tmp[sa[i]] = tmp[sa[i - 1]] + (compare(sa[i - 1], sa[i]) < 0 ? 1 : 0);
    }
    // Copy tmp to rank
    for (int i = 0; i < n; i++) {
      rank[i] = tmp[i];
    }

    // If all ranks are unique, stop
    if (rank[sa[n - 1]] == n - 1) break;
  }

  // Output
  print("Suffix Array for '$s':");
  for (int i = 0; i < n; i++) {
    print('${sa[i]}: ${s.substring(sa[i])}');
  }
}

