import 'dart:io';
import 'dart:math';

class Point {
  final int x, y;
  Point(this.x, this.y);

  @override
  String toString() => '($x, $y)';
}

// Cross product of OA and OB vectors (with O as origin)
int cross(Point o, Point a, Point b) {
  return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
}

// Distance squared between two points
int dist2(Point a, Point b) {
  int dx = a.x - b.x, dy = a.y - b.y;
  return dx * dx + dy * dy;
}

