void main(List<String> args) {
  // Parse inputs:
  // Usage: dart run <file.dart> <k> <item1> <item2> ...
  // If no args are given, use a default example.
  late int k;
  late List<String> items;

  if (args.isEmpty) {
    items = ['A', 'B', 'C', 'D'];
    k = 2;
    print('No args provided. Using default input: k=$k, items=$items');
    print('Usage: dart run <file.dart> <k> <item1> <item2> ...');
  } else {
    final parsedK = int.tryParse(args[0]);
    if (parsedK == null) {
      print('First argument must be an integer k (size of combinations). Got: ${args[0]}');
      print('Usage: dart run <file.dart> <k> <item1> <item2> ...');
      return;
    }
    k = parsedK;
    items = args.length > 1 ? args.sublist(1) : <String>[];
  }

  final n = items.length;

  // Validate k
  if (k < 0 || k > n) {
    print('k must be between 0 and n (inclusive). n=$n, k=$k');
    return;
  }

  // Special case: one empty combination when k == 0
  if (k == 0) {
    print('[]');
    print('Total combinations: 1');
    return;
  }

  // Iterative k-combination generation using index array.
  // indices[i] points into items for the i-th element of the current combination.
  final indices = List<int>.generate(k, (i) => i);
  int count = 0;

  while (true) {
    // Emit current combination
    final combo = List<String>.generate(k, (i) => items[indices[i]]);
    print(combo);
    count++;

    // Find the rightmost index that can be incremented
    int i = k - 1;
    while (i >= 0 && indices[i] == i + n - k) {
      i--;
    }
    if (i < 0) break; // All combinations generated

    // Increment this index and reset the suffix to the lowest possible values
    indices[i]++;
    for (int j = i + 1; j < k; j++) {
      indices[j] = indices[j - 1] + 1;
    }
  }

  print('Total combinations: $count');
}

