// A complete Dart program implementing basic quaternion mathematics.
// This includes a Quaternion class with operations like addition, multiplication,
// conjugate, magnitude, normalization, and inverse.
// The main function demonstrates usage with examples.

import 'dart:math' as math;

class Quaternion {
  final double w;
  final double x;
  final double y;
  final double z;

  Quaternion(this.w, this.x, this.y, this.z);

  // Addition of two quaternions
  Quaternion add(Quaternion other) {
    return Quaternion(
      w + other.w,
      x + other.x,
      y + other.y,
      z + other.z,
    );
  }

  // Multiplication of two quaternions (Hamilton product)
  Quaternion multiply(Quaternion other) {
    return Quaternion(
      w * other.w - x * other.x - y * other.y - z * other.z,
      w * other.x + x * other.w + y * other.z - z * other.y,
      w * other.y - x * other.z + y * other.w + z * other.x,
      w * other.z + x * other.y - y * other.x + z * other.w,
    );
  }

  // Conjugate of the quaternion
  Quaternion conjugate() {
    return Quaternion(w, -x, -y, -z);
  }

  // Magnitude (norm) of the quaternion
  double magnitude() {
    return math.sqrt(w * w + x * x + y * y + z * z);
  }

  // Normalize the quaternion (unit quaternion)
  Quaternion normalize() {
    double mag = magnitude();
    if (mag == 0) {
      throw Exception('Cannot normalize zero quaternion');
    }
    return Quaternion(w / mag, x / mag, y / mag, z / mag);
  }

  // Inverse of the quaternion (for unit quaternions)
  Quaternion inverse() {
    double magSquared = w * w + x * x + y * y + z * z;
    if (magSquared == 0) {
      throw Exception('Cannot invert zero quaternion');
    }
    return Quaternion(w / magSquared, -x / magSquared, -y / magSquared, -z / magSquared);
  }

  // Rotate a 3D vector using this quaternion (assumes unit quaternion)
  List<double> rotateVector(List<double> vector) {
    if (vector.length != 3) {
      throw Exception('Vector must be 3D');
    }
    Quaternion vecQuat = Quaternion(0, vector[0], vector[1], vector[2]);
    Quaternion result = this.multiply(vecQuat).multiply(this.inverse());
    return [result.x, result.y, result.z];
  }

  @override
  String toString() {
    return 'Quaternion($w, $x, $y, $z)';
  }
}

