  // Men's preferences: menPrefs[man][rank] = woman index
  const menPrefs = [
    [0, 1, 2, 3], // A's preferences: W, X, Y, Z
    [2, 0, 1, 3], // B's preferences: Y, W, X, Z
    [1, 2, 3, 0], // C's preferences: X, Y, Z, W
    [0, 2, 3, 1], // D's preferences: W, Y, Z, X
  ];

