  // Example input: list of points
  List<Point> points = [
    Point(0, 3),
    Point(2, 2),
    Point(1, 1),
    Point(2, 1),
    Point(3, 0),
    Point(0, 0),
    Point(3, 3),
  ];

  if (points.length <= 1) {
    print('Convex hull: $points');
    return;
  }

  // Step 1: Find the point with the lowest y (and leftmost if tie)
  points.sort((a, b) {
    if (a.y != b.y) return a.y - b.y;
    return a.x - b.x;
  });
  Point p0 = points[0];

  // Step 2: Sort points by polar angle with p0, breaking ties by distance
  points = [p0] +
      points.sublist(1)
        ..sort((a, b) {
          int cp = cross(p0, a, b);
          if (cp == 0) {
            // Collinear: closer comes first
            return dist2(p0, a) - dist2(p0, b);
          }
          return -cp; // Sort by angle (counter-clockwise)
        });

  // Step 3: Graham scan
  List<Point> hull = [];
  for (var p in points) {
    while (hull.length >= 2 &&
        cross(hull[hull.length - 2], hull[hull.length - 1], p) <= 0) {
      hull.removeLast();
    }
    hull.add(p);
  }

  print('Convex hull:');
  for (var p in hull) {
    print(p);
  }
}

