// A complete Dart program implementing a Fenwick Tree (Binary Indexed Tree).
// The Fenwick Tree supports efficient updates and prefix sum queries.

class FenwickTree {
  late List<int> tree;
  final int n;

  FenwickTree(this.n) {
    tree = List<int>.filled(n + 1, 0);
  }

  // Update the value at index by adding val (supports increments).
  void update(int index, int val) {
    while (index <= n) {
      tree[index] += val;
      index += index & -index;
    }
  }

  // Query the prefix sum from 1 to index.
  int query(int index) {
    int sum = 0;
    while (index > 0) {
      sum += tree[index];
      index -= index & -index;
    }
    return sum;
  }
}

