void main() {
  // Input text and pattern to search
  String text = "ababcabcabababd";
  String pattern = "ababd";

  // Constants for rolling hash
  const int prime = 101; // Prime modulus to reduce collisions
  const int base = 256;  // Base for the hash calculation (assuming ASCII-like characters)

  int n = text.length;
  int m = pattern.length;

  // Check if pattern is longer than text
  if (m > n) {
    print("Pattern longer than text.");
    return;
  }

  int patternHash = 0; // Hash value for the pattern
  int windowHash = 0;  // Hash value for the current text window
  int h = 1;           // Value of base^(m-1) mod prime

  // Precompute h = base^(m-1) mod prime
  for (int i = 0; i < m - 1; i++) {
    h = (h * base) % prime;
  }

  // Calculate initial hash values for pattern and first window of text
  for (int i = 0; i < m; i++) {
    patternHash = (base * patternHash + pattern.codeUnitAt(i)) % prime;
    windowHash = (base * windowHash + text.codeUnitAt(i)) % prime;
  }

  List<int> matches = []; // List to store starting indices of matches

  // Slide the pattern over the text one position at a time
  for (int i = 0; i <= n - m; i++) {
    // Check if the hash values match
    if (patternHash == windowHash) {
      bool match = true;
      // Verify characters one by one to confirm match
      for (int j = 0; j < m; j++) {
        if (text[i + j] != pattern[j]) {
          match = false;
          break;
        }
      }
      if (match) {
        matches.add(i); // Add index to matches if full match found
      }
    }

    // Calculate hash for the next window if not at the end
    if (i < n - m) {
      windowHash = (base * (windowHash - text.codeUnitAt(i) * h) + text.codeUnitAt(i + m)) % prime;
      // Adjust for negative hash value
      if (windowHash < 0) {
        windowHash += prime;
      }
    }
  }

  // Output results based on whether matches were found
  if (matches.isEmpty) {
    print('Pattern not found in text.');
  } else {
    print('Pattern found at indices: $matches');
  }
}
```

