void main() {
  // Example graph represented as adjacency list
  // Graph with 8 vertices (0-7)
  final int vertices = 8;
  final List<List<int>> graph = List.generate(vertices, (_) => []);

  // Building the graph edges
  graph[0].add(1);
  graph[1].add(2);
  graph[2].add(0);
  graph[2].add(3);
  graph[3].add(4);
  graph[4].add(5);
  graph[4].add(7);
  graph[5].add(6);
  graph[6].add(4);
  graph[6].add(7);

  // Step 1: Perform DFS and store vertices by finish time
  List<bool> visited = List.filled(vertices, false);
  List<int> finishStack = [];

  void dfsFirstPass(int vertex) {
    visited[vertex] = true;
    for (int neighbor in graph[vertex]) {
      if (!visited[neighbor]) {
        dfsFirstPass(neighbor);
      }
    }
    finishStack.add(vertex);
  }

  // Run first DFS pass on all vertices
  for (int i = 0; i < vertices; i++) {
    if (!visited[i]) {
      dfsFirstPass(i);
    }
  }

  // Step 2: Create transpose graph
  List<List<int>> transposeGraph = List.generate(vertices, (_) => []);
  for (int v = 0; v < vertices; v++) {
    for (int neighbor in graph[v]) {
      transposeGraph[neighbor].add(v);
    }
  }

  // Step 3: Perform DFS on transpose graph in reverse finish order
  visited = List.filled(vertices, false);
  List<List<int>> stronglyConnectedComponents = [];

  void dfsSecondPass(int vertex, List<int> component) {
    visited[vertex] = true;
    component.add(vertex);
    for (int neighbor in transposeGraph[vertex]) {
      if (!visited[neighbor]) {
        dfsSecondPass(neighbor, component);
      }
    }
  }

  // Process vertices in reverse finish order
  while (finishStack.isNotEmpty) {
    int vertex = finishStack.removeLast();
    if (!visited[vertex]) {
      List<int> component = [];
      dfsSecondPass(vertex, component);
      stronglyConnectedComponents.add(component);
    }
  }

  // Print the results
  print('Kosaraju\'s Algorithm - Strongly Connected Components:');
  print('======================================================');
  print('Original Graph Edges:');
  for (int v = 0; v < vertices; v++) {
