      print('  $v -> $neighbor');
    }
  }

  print('\nNumber of SCCs found: ${stronglyConnectedComponents.length}');
  print('\nStrongly Connected Components:');
  for (int i = 0; i < stronglyConnectedComponents.length; i++) {
    stronglyConnectedComponents[i].sort();
    print('SCC ${i + 1}: {${stronglyConnectedComponents[i].join(', ')}}');
  }

  // Additional test with a different graph
  print('\n\nTesting with another graph:');
  print('===========================');

