// Demonstrates spread operators (...) and null-aware spread (...?) in Dart collections.
@pragma('vm:entry-point')
void main() {
  // List spreads
  final List<int> baseList = [2, 3];
  final List<int> listSpread = [1, ...baseList, 4, ...[5, 6]];
  print('List spread: $listSpread');

  // Null-aware list spreads
  List<int>? maybeList;
  final List<int> listWithNull = [0, ...?maybeList, 9]; // maybeList is null
  maybeList = [7, 8];
  final List<int> listWithValues = [0, ...?maybeList, 9]; // maybeList has values
  print('Null-aware list spread when null: $listWithNull');
  print('Null-aware list spread when non-null: $listWithValues');

  // Set spreads (note: sets deduplicate elements)
  final Set<int> setA = {1, 2, 3};
  final Set<int> setB = {3, 4, 5};
  final Set<int> setSpread = {...setA, 3, ...setB, 6};
  print('Set spread (deduplicated): $setSpread');

  // Null-aware set spreads
  Set<int>? maybeSet;
  final Set<int> setWithNull = {...?maybeSet, 10}; // maybeSet is null
  maybeSet = {7, 8};
  final Set<int> setWithValues = {...?maybeSet, 10}; // maybeSet has values
  print('Null-aware set spread when null: $setWithNull');
  print('Null-aware set spread when non-null: $setWithValues');

  // Spread a set into a list (type change is okay when element types match)
  final List<int> listFromSet = [...setSpread];
  print('Spread a set into a list: $listFromSet');

  // Map spreads (later entries overwrite earlier ones for the same key)
  final Map<String, int> map1 = {'a': 1, 'b': 2};
  final Map<String, int> map2 = {'b': 20, 'c': 3};
  final Map<String, int> mapSpread = {...map1, ...map2, 'd': 4};
  print('Map spread with overwrite: $mapSpread');

  // Null-aware map spreads
  Map<String, int>? maybeMap;
  final Map<String, int> mapWithNull = {...?maybeMap, 'x': 42}; // maybeMap is null
  maybeMap = {'y': 7};
  final Map<String, int> mapWithValues = {...?maybeMap, 'x': 42}; // maybeMap has values
  print('Null-aware map spread when null: $mapWithNull');
  print('Null-aware map spread when non-null: $mapWithValues');

  // Spread map entries into a list of MapEntry objects
  final List<MapEntry<String, int>> entryList = [...mapSpread.entries];
  print('List of map entries via spread: $entryList');
}

