  );

  // Find max activity for coloring
  int maxActivity = activity.expand((d) => d).reduce(max);

  // Map activity count to heat levels (0: none, 1: low, 2: medium, 3: high)
  int heatLevel(int count) {
    if (count == 0) return 0;
    if (count < maxActivity * 0.33) return 1;
    if (count < maxActivity * 0.66) return 2;
    return 3;
  }

  // Heatmap color chars
  const heatChars = [' ', '.', '*', '#'];

  // Print header
  print('User Activity Heatmap (Day x Hour)');
  print('      ' + hours.map((h) => h.padLeft(2)).join(' '));
  print('     +' + '-' * (hours.length * 3 - 1));

  // Print each day row
