import 'dart:io';

/// Console-based user feedback form.
///
/// To run:
///   dart run feedback_form.dart
///
/// The program keeps asking for feedback until the user presses ENTER
/// at the “name” prompt or answers anything other than “y” when asked
/// whether to add another entry.
@pragma('vm:entry-point')
void main() {
  print('===== Welcome to the User Feedback Form =====\n'
      'Press ENTER at the name prompt to exit at any time.\n');

  final feedbacks = <Map<String, dynamic>>[];

  while (true) {
    stdout.write('Your name: ');
    final name = stdin.readLineSync()?.trim() ?? '';
    if (name.isEmpty) break;

    // ── Email ───────────────────────────────────────────────────────────
    String email;
    final emailRegExp = RegExp(r'^[\w\.-]+@[\w\.-]+\.\w+$');
    while (true) {
      stdout.write('Your e-mail: ');
      email = stdin.readLineSync()?.trim() ?? '';
      if (emailRegExp.hasMatch(email)) break;
      print('  → Invalid e-mail format, please try again.');
    }

    // ── Rating ──────────────────────────────────────────────────────────
    int rating;
    while (true) {
      stdout.write('Rate us (1-5): ');
      rating = int.tryParse(stdin.readLineSync()?.trim() ?? '') ?? 0;
      if (rating >= 1 && rating <= 5) break;
      print('  → Rating must be an integer between 1 and 5.');
    }

    // ── Optional Comments ───────────────────────────────────────────────
    stdout.write('Any additional comments? (optional): ');
    final comments = stdin.readLineSync()?.trim() ?? '';

    // Store the entry.
    feedbacks.add(<String, dynamic>{
      'name': name,
      'email': email,
      'rating': rating,
      'comments': comments,
    });

    print('\nThank you, $name, for your feedback!\n');

    // Add another?
    stdout.write('Add another feedback? (y/N): ');
    final again = stdin.readLineSync()?.trim().toLowerCase() ?? '';
    if (again != 'y') break;
    print('');
  }

  // ── Summary ───────────────────────────────────────────────────────────
  if (feedbacks.isEmpty) {
    print('\nNo feedback submitted — goodbye!');
    return;
  }

  final totalRating =
      feedbacks.fold<int>(0, (sum, f) => sum + (f['rating'] as int));
  final avgRating =
      (totalRating / feedbacks.length).toStringAsFixed(2);

  print('\n========== Feedback Summary ==========');
  for (final f in feedbacks) {
    print('\nName     : ${f['name']}'
        '\nE-mail   : ${f['email']}'
        '\nRating   : ${f['rating']} / 5'
        '\nComments : '
        '${(f['comments'] as String).isEmpty ? '– none –' : f['comments']}');
  }
  print('\n--------------------------------------'
      '\nTotal submissions : ${feedbacks.length}'
      '\nAverage rating    : $avgRating / 5'
      '\n======================================');
}

