void main() {
  // Rabin–Karp string search algorithm
  // Input: first line – pattern to search, second line – text to scan
  // Output: list of starting indices where pattern occurs in text

  const int base = 256;   // Alphabet size (ASCII)
  const int prime = 101;  // Modulus for hashing (a small prime)

  // Read input from stdin
  final pattern = stdin.readLineSync();
  final text = stdin.readLineSync();

  // Handle null inputs
  if (pattern == null || text == null) {
    stderr.writeln('Error: Provide pattern and text on two separate lines.');
    exit(1);
  }

  final int m = pattern.length;
  final int n = text.length;

  // Check if pattern is empty or longer than text
  if (m == 0 || m > n) {
    print('[]');
    return;
  }

  // Pre-compute (base^(m-1)) % prime for rolling hash
  int highPow = 1;
  for (int i = 0; i < m - 1; i++) {
    highPow = (highPow * base) % prime;
  }

  int patHash = 0;    // Hash of pattern
  int winHash = 0;    // Hash of current window in text

  // Compute initial hashes for pattern and first window of text
  for (int i = 0; i < m; i++) {
    patHash = (patHash * base + pattern.codeUnitAt(i)) % prime;
    winHash = (winHash * base + text.codeUnitAt(i)) % prime;
  }

  final List<int> matches = [];  // List to store matching indices

  // Slide the window through the text
  for (int i = 0; i <= n - m; i++) {
    // If hash values match, verify characters to avoid false positives
    if (patHash == winHash && text.substring(i, i + m) == pattern) {
      matches.add(i);
    }

    // Update the hash for the next window if not at the end
    if (i < n - m) {
      // Remove leading character's contribution and add next character
      winHash = (winHash - text.codeUnitAt(i) * highPow) % prime;
      // Ensure non-negative modulo
      if (winHash < 0) {
        winHash += prime;
      }
      winHash = (winHash * base + text.codeUnitAt(i + m)) % prime;
    }
  }

  print(matches);  // Output the list of matches
}
