import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // ---------- Configuration ----------
  const int width = 80;         // Console columns
  const int height = 24;        // Console rows
  const int siteCount = 10;     // How many Voronoi sites to create
  // -----------------------------------

  // Generate random sites inside the grid
  final rng = Random();
  final List<Point<double>> sites = List.generate(
    siteCount,
    (_) => Point<double>(
      rng.nextInt(width).toDouble(),
      rng.nextInt(height).toDouble(),
    ),
  );

  // Characters used to label each site’s region
  const String labels =
      '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
  if (siteCount > labels.length) {
    print('Error: Not enough label characters for $siteCount sites.');
    return;
  }

  // Announce where each site is located
  for (int i = 0; i < siteCount; i++) {
    final p = sites[i];
    print('${labels[i]} => (${p.x.toInt()}, ${p.y.toInt()})');
  }
  print('');

  // Helper to compute squared distance (avoids expensive sqrt)
  num distanceSquared(Point<double> p, double x, double y) {
    final dx = p.x - x;
    final dy = p.y - y;
    return dx * dx + dy * dy;
  }

  // Build an ASCII grid containing the Voronoi diagram
  final buffer = StringBuffer();
  for (int y = 0; y < height; y++) {
    for (int x = 0; x < width; x++) {
      int closest = 0;
      num best = distanceSquared(sites[0], x.toDouble(), y.toDouble());
      bool tie = false;

      // Find the nearest site
      for (int s = 1; s < siteCount; s++) {
        final d = distanceSquared(sites[s], x.toDouble(), y.toDouble());
        if (d < best - 1e-9) {
          best = d;
          closest = s;
          tie = false;
        } else if ((d - best).abs() < 1e-9) {
          tie = true; // Equidistant: mark as boundary
        }
      }

      // Output the character for this cell
      buffer.write(tie ? '.' : labels[closest]);
    }
    buffer.writeln();
  }

  // Display the ASCII Voronoi diagram
  print(buffer.toString());
}

