class Node {
  int value;
  Node? left;
  Node? right;

  Node(this.value, {this.left, this.right});
}

@pragma('vm:entry-point')
void main() {
  // Create a sample binary tree:
  //       1
  //     /   \
  //    2     3
  //   / \   / \
  //  4   5 6   7
  Node root = Node(1,
      left: Node(2, left: Node(4), right: Node(5)),
      right: Node(3, left: Node(6), right: Node(7)));

  // Define inorder traversal (Left, Root, Right)
  void inorder(Node? node, List<int> result) {
    if (node == null) return;
    inorder(node.left, result);
    result.add(node.value);
    inorder(node.right, result);
  }

  // Define preorder traversal (Root, Left, Right)
  void preorder(Node? node, List<int> result) {
    if (node == null) return;
    result.add(node.value);
    preorder(node.left, result);
    preorder(node.right, result);
  }

  // Define postorder traversal (Left, Right, Root)
  void postorder(Node? node, List<int> result) {
    if (node == null) return;
    postorder(node.left, result);
    postorder(node.right, result);
    result.add(node.value);
  }

  // Perform traversals and print results
  List<int> inorderResult = [];
  inorder(root, inorderResult);
  print('Inorder traversal: ${inorderResult.join(' ')}');

  List<int> preorderResult = [];
  preorder(root, preorderResult);
  print('Preorder traversal: ${preorderResult.join(' ')}');

  List<int> postorderResult = [];
  postorder(root, postorderResult);
  print('Postorder traversal: ${postorderResult.join(' ')}');
}

