void main(List<String> args) {
  /* -------------------------------------------------------------
   * Chinese Remainder Theorem (pair-wise coprime moduli)
   *
   * Usage:
   *   dart run crt.dart n a1 m1 a2 m2 ... an mn
   *
   * Example for the system
   *   x ≡ 2 (mod 3)
   *   x ≡ 3 (mod 5)
   *   x ≡ 2 (mod 7)
   *
   *   dart run crt.dart 3 2 3 3 5 2 7
   * ------------------------------------------------------------*/
  if (args.isEmpty) {
    stderr.writeln('Usage: dart run crt.dart n a1 m1 a2 m2 ...');
    exit(1);
  }

  final int n = int.parse(args.first);
  if (args.length != 1 + 2 * n) {
    stderr.writeln('Error: Expected ${1 + 2 * n} arguments, but got ${args.length}.');
    exit(1);
  }

  /* ---------- Local helpers (all scoped inside main) ---------- */

  // Greatest-common divisor (Euclid).
  BigInt gcd(BigInt a, BigInt b) {
    while (b != BigInt.zero) {
      final BigInt t = a % b;
      a = b;
      b = t;
    }
    return a.abs();
  }

  // Modular multiplicative inverse using extended Euclid.
  BigInt modInverse(BigInt a, BigInt m) {
    BigInt r0 = a, r1 = m;
    BigInt t0 = BigInt.one, t1 = BigInt.zero;

    while (r1 != BigInt.zero) {
      final BigInt q = r0 ~/ r1;

      final BigInt rNext = r0 - q * r1;
      r0 = r1;
      r1 = rNext;

      final BigInt tNext = t0 - q * t1;
      t0 = t1;
      t1 = tNext;
    }

    if (r0 != BigInt.one) {
      throw Exception('Modular inverse does not exist (numbers not coprime).');
    }

    return (t0 % m + m) % m; // ensure positive
  }

  /* ------------------ Parse the input vectors ----------------- */
  final List<BigInt> a = List<BigInt>.generate(
      n, (i) => BigInt.parse(args[1 + 2 * i]));
  final List<BigInt> m = List<BigInt>.generate(
      n, (i) => BigInt.parse(args[2 + 2 * i]));

  /* ----------- Validate pair-wise coprimeness of moduli -------- */
  for (int i = 0; i < n; ++i) {
    for (int j = i + 1; j < n; ++j) {
      if (gcd(m[i], m[j]) != BigInt.one) {
        stderr.writeln('Error: Moduli must be pair-wise coprime.');
        exit(1);
      }
    }
  }

  /* ----- Core CRT: x ≡ a[i] (mod m[i])  for all i = 1‥n ------ */
  BigInt M = BigInt.one; // Product of all moduli
  for (final BigInt mod in m) {
    M *= mod;
  }

  BigInt x = BigInt.zero;
  for (int i = 0; i < n; ++i) {
    final BigInt Mi = M ~/ m[i];
    final BigInt inv = modInverse(Mi % m[i], m[i]);
    x += a[i] * Mi * inv;
  }

  final BigInt solution = (x % M + M) % M; // smallest non-negative solution

  /* --------------------------- Output ------------------------- */
  stdout.writeln('x ≡ $solution (mod $M)');
}

