  int n = items.length;
  if (k < 0 || k > n) {
    print('Invalid combination size.');
    return;
  }

  // This will hold all the generated combinations
  List<List<String>> combinations = [];

  // Initialize the first combination indices: [0, 1, 2, ..., k-1]
  List<int> indices = List<int>.generate(k, (i) => i);

  while (true) {
    // Build current combination based on indices
    combinations.add(indices.map((i) => items[i]).toList());

    // Find the rightmost index that can be incremented
    int i;
    for (i = k - 1; i >= 0; i--) {
      if (indices[i] < i + n - k) {
        break;
      }
    }

    // If no such index, we've generated all combinations
    if (i < 0) {
      break;
    }

    // Increment this index
    indices[i]++;

    // Reset subsequent indices
    for (int j = i + 1; j < k; j++) {
      indices[j] = indices[j - 1] + 1;
    }
  }

  // Print out all combinations
  for (var combo in combinations) {
    print(combo);
  }
}

