void main(List<String> args) {
  // Expect exactly two command-line arguments: the strings to compare.
  if (args.length != 2) {
    print('Usage: dart run <script.dart> <string1> <string2>');
    print('Computes the Levenshtein (edit) distance between the two strings.');
    return;
  }

  final String a = args[0];
  final String b = args[1];
  final int m = a.length;
  final int n = b.length;

  // Dynamic-programming table where dp[i][j] is the distance
  // between the first i chars of a and the first j chars of b.
  final List<List<int>> dp =
      List.generate(m + 1, (_) => List.filled(n + 1, 0));

  // Initialization: transforming empty string to prefixes.
  for (int i = 0; i <= m; i++) dp[i][0] = i;
  for (int j = 0; j <= n; j++) dp[0][j] = j;

  // Fill the table.
  for (int i = 1; i <= m; i++) {
    for (int j = 1; j <= n; j++) {
      final int cost = a.codeUnitAt(i - 1) == b.codeUnitAt(j - 1) ? 0 : 1;

      final int deletion = dp[i - 1][j] + 1;        // delete a char from a
      final int insertion = dp[i][j - 1] + 1;       // insert a char into a
      final int substitution = dp[i - 1][j - 1] + cost; // substitute/keep

      // Minimum of the three operations.
      dp[i][j] = deletion < insertion
          ? (deletion < substitution ? deletion : substitution)
          : (insertion < substitution ? insertion : substitution);
    }
  }

  print('Levenshtein distance between "$a" and "$b": ${dp[m][n]}');
}

