  // A large value to represent "infinity"
  const int INF = 1 << 60;

  // Number of vertices in the graph
  const int V = 5;

  // List of edges in the graph: each edge is [u, v, weight]
  final List<List<int>> edges = [
    [0, 1, 6],
    [0, 2, 7],
    [1, 2, 8],
    [1, 3, 5],
    [1, 4, -4],
    [2, 3, -3],
    [2, 4, 9],
    [3, 1, -2],
    [4, 3, 7],
  ];

  // The source vertex from which to calculate distances
  const int source = 0;

  // Initialize distances array: dist[i] = INF for all i, except dist[source] = 0
  List<int> dist = List<int>.filled(V, INF);
  dist[source] = 0;

  // Relax all edges V-1 times
  for (int i = 0; i < V - 1; i++) {
    bool updated = false;
    for (final edge in edges) {
      int u = edge[0], v = edge[1], w = edge[2];
      if (dist[u] != INF && dist[u] + w < dist[v]) {
        dist[v] = dist[u] + w;
        updated = true;
      }
    }
    // If no update in this pass, we can stop early
    if (!updated) break;
  }

  // Check for negative-weight cycles
  bool hasNegativeCycle = false;
  for (final edge in edges) {
    int u = edge[0], v = edge[1], w = edge[2];
    if (dist[u] != INF && dist[u] + w < dist[v]) {
      hasNegativeCycle = true;
      break;
    }
  }

  if (hasNegativeCycle) {
    print('Graph contains a negative-weight cycle');
  } else {
    print('Vertex\tDistance from Source');
    for (int i = 0; i < V; i++) {
      String d = dist[i] == INF ? '∞' : dist[i].toString();
      print('$source -> $i\t$d');
    }
  }
}

