void main() {
  // Sample 2D data points
  List<List<double>> points = [
    [1.0, 2.0],
    [1.5, 1.8],
    [5.0, 8.0],
    [8.0, 8.0],
    [1.0, 0.6],
    [9.0, 11.0],
  ];

  // Desired number of clusters
  int k = 2;

  // Initialize each point as its own cluster (store point indices)
  List<List<int>> clusters = List.generate(points.length, (i) => [i]);

  // Euclidean distance between two points
  double distance(List<double> a, List<double> b) {
    double sum = 0;
    for (int i = 0; i < a.length; i++) {
      double diff = a[i] - b[i];
      sum += diff * diff;
    }
    return sqrt(sum);
  }

  // Agglomerative clustering (single-link)
  while (clusters.length > k) {
    double minDist = double.infinity;
    int mergeA = 0, mergeB = 1;

    // Find the two closest clusters
    for (int i = 0; i < clusters.length - 1; i++) {
      for (int j = i + 1; j < clusters.length; j++) {
        // single-link: minimum distance between any two points in the clusters
        double d = double.infinity;
        for (int idx1 in clusters[i]) {
          for (int idx2 in clusters[j]) {
            double dist = distance(points[idx1], points[idx2]);
            if (dist < d) d = dist;
          }
        }
        if (d < minDist) {
          minDist = d;
          mergeA = i;
          mergeB = j;
        }
      }
    }

    // Merge the two closest clusters
    List<int> newCluster = []
      ..addAll(clusters[mergeA])
      ..addAll(clusters[mergeB]);
    // Remove the clusters (remove higher index first)
    clusters.removeAt(mergeB);
    clusters.removeAt(mergeA);
    clusters.add(newCluster);
  }

  // Output the resulting clusters
  for (int i = 0; i < clusters.length; i++) {
    print('Cluster $i:');
    for (int idx in clusters[i]) {
      print('  Point $idx: ${points[idx]}');
    }
  }
}

