/// Feed it 9 lines of digits (0 or . for blanks) through stdin,
/// or just run it and it will solve an embedded sample puzzle.
@pragma('vm:entry-point')
void main() {
  // ---------------------------------------------------------------------------
  // 1. Obtain a puzzle: try reading 9 non-empty lines from stdin, otherwise use
  //    a hard-coded example.
  // ---------------------------------------------------------------------------
  List<String> rawLines = [];
  for (int i = 0; i < 9; i++) {
    final line = stdin.readLineSync();
    if (line == null || line.trim().isEmpty) break;
    rawLines.add(line.trim());
  }

  List<List<int>> board;
  if (rawLines.length == 9) {
    // Parse the input lines into a 9×9 matrix.
    board = List.generate(9, (_) => List.filled(9, 0));
    for (int r = 0; r < 9; r++) {
      int c = 0;
      for (var ch in rawLines[r].split('')) {
        if (RegExp(r'[0-9.]').hasMatch(ch) && c < 9) {
          board[r][c++] = ch == '.' ? 0 : int.parse(ch);
        }
      }
    }
  } else {
    // Fallback example (difficulty: hard).
    board = [
      [0, 0, 0, 2, 6, 0, 7, 0, 1],
      [6, 8, 0, 0, 7, 0, 0, 9, 0],
      [1, 9, 0, 0, 0, 4, 5, 0, 0],
      [8, 2, 0, 1, 0, 0, 0, 4, 0],
      [0, 0, 4, 6, 0, 2, 9, 0, 0],
      [0, 5, 0, 0, 0, 3, 0, 2, 8],
      [0, 0, 9, 3, 0, 0, 0, 7, 4],
      [0, 4, 0, 0, 5, 0, 0, 3, 6],
      [7, 0, 3, 0, 1, 8, 0, 0, 0],
    ];
  }

  // ---------------------------------------------------------------------------
  // 2. Helper that checks if placing `num` at (row, col) keeps the board valid.
  // ---------------------------------------------------------------------------
  bool isValid(int row, int col, int num) {
    // Row & column.
    for (int i = 0; i < 9; i++) {
      if (board[row][i] == num || board[i][col] == num) return false;
    }
    // 3×3 sub-grid.
    final sr = (row ~/ 3) * 3, sc = (col ~/ 3) * 3;
    for (int r = sr; r < sr + 3; r++) {
      for (int c = sc; c < sc + 3; c++) {
        if (board[r][c] == num) return false;
      }
    }
    return true;
  }

  // ---------------------------------------------------------------------------
  // 3. Classic backtracking solver.
  // ---------------------------------------------------------------------------
  bool solve(int row, int col) {
    if (row == 9) return true;           // Reached end: success.
    if (col == 9) return solve(row + 1, 0);
    if (board[row][col] != 0) return solve(row, col + 1);

    for (int num = 1; num <= 9; num++) {
      if (isValid(row, col, num)) {
        board[row][col] = num;
        if (solve(row, col + 1)) return true;
        board[row][col] = 0;             // Backtrack.
      }
    }
    return false;                        // Trigger backtracking.
  }

  // ---------------------------------------------------------------------------
  // 4. Run the solver and print the result.
  // ---------------------------------------------------------------------------
  if (solve(0, 0)) {
    for (var row in board) {
      stdout.writeln(row.join(' '));
    }
  } else {
    stdout.writeln('No solution found.');
  }
}

