import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // ------------------------------------------------------------
  // Perceptron demonstration on the linearly separable AND problem
  // ------------------------------------------------------------

  // Training data: inputs and expected outputs (AND gate).
  final List<List<double>> inputs = [
    [0, 0],
    [0, 1],
    [1, 0],
    [1, 1],
  ];
  final List<int> targets = [0, 0, 0, 1];

  // Hyper-parameters.
  const int epochs = 30;
  const double learningRate = 0.1;

  // Randomly initialize weights and bias.
  final Random rng = Random();
  List<double> weights =
      List<double>.generate(inputs.first.length, (_) => rng.nextDouble() * 2 - 1);
  double bias = rng.nextDouble() * 2 - 1;

  // Helper closure: calculate perceptron output (step activation).
  int predict(List<double> x) {
    double sum = bias;
    for (int i = 0; i < x.length; i++) sum += weights[i] * x[i];
    return sum >= 0 ? 1 : 0;
  }

  // Training loop.
  for (int epoch = 1; epoch <= epochs; epoch++) {
    int errorCount = 0;

    for (int i = 0; i < inputs.length; i++) {
      int output = predict(inputs[i]);
      int error = targets[i] - output;

      // Weight & bias update.
      for (int j = 0; j < weights.length; j++) {
        weights[j] += learningRate * error * inputs[i][j];
      }
      bias += learningRate * error;

      if (error != 0) errorCount++;
    }

    print('Epoch $epoch | errors: $errorCount | weights: $weights | bias: $bias');
    if (errorCount == 0) break; // Stop early if perfectly classified.
  }

  // Final evaluation.
  print('\nFinal evaluation:');
  for (int i = 0; i < inputs.length; i++) {
    print('Input ${inputs[i]} => predicted ${predict(inputs[i])}, target ${targets[i]}');
  }
}

