import 'dart:io';

@pragma('vm:entry-point')
void main(List<String> args) {
  /*
   * Kosaraju’s algorithm for finding strongly–connected components (SCC)
   * -------------------------------------------------------------------
   * Input format (from stdin):
   *   n m          – number of vertices (1 … n) and directed edges
   *   u1 v1
   *   u2 v2
   *   ...
   *   um vm        – m directed edges ui → vi (1-based indices)
   *
   * Output (to stdout):
   *   k            – number of SCCs
   *   c1 c2 … cn   – component id (1-based) for every vertex 1…n
   */

  /* ---------- 1. Read and tokenize stdin ---------- */
  final List<int> tok = <int>[];
  String? line;
  while ((line = stdin.readLineSync()) != null) {
    if (line!.isEmpty) continue;
    tok.addAll(
      line.split(RegExp(r'\s+')).where((s) => s.isNotEmpty).map(int.parse),
    );
  }
  if (tok.length < 2) {
    stderr.writeln('Input must start with “n m”.');
    return;
  }
  int idx = 0;
  final int n = tok[idx++]; // vertices
  final int m = tok[idx++]; // edges

  /* ---------- 2. Build graph and its transpose ---------- */
  final List<List<int>> g = List.generate(n, (_) => <int>[]);
  final List<List<int>> gt = List.generate(n, (_) => <int>[]);
  for (int i = 0; i < m; ++i) {
    if (idx + 1 >= tok.length) {
      stderr.writeln('Insufficient edge data.');
      return;
    }
    final int u = tok[idx++] - 1; // 0-based
    final int v = tok[idx++] - 1;
    if (u < 0 || u >= n || v < 0 || v >= n) continue; // skip invalid
    g[u].add(v);
    gt[v].add(u);
  }

  /* ---------- 3. First DFS – store vertices by finish time ---------- */
  final List<bool> vis = List<bool>.filled(n, false);
  final List<int> order = <int>[];

  void dfs1(int v) {
    vis[v] = true;
    for (final w in g[v]) {
      if (!vis[w]) dfs1(w);
    }
    order.add(v);
  }

  for (int v = 0; v < n; ++v) {
    if (!vis[v]) dfs1(v);
  }

  /* ---------- 4. Second DFS on the transpose graph ---------- */
  vis.fillRange(0, n, false);
  final List<int> comp = List<int>.filled(n, -1);
  int compCnt = 0;

  void dfs2(int v) {
    vis[v] = true;
    comp[v] = compCnt;
    for (final w in gt[v]) {
      if (!vis[w]) dfs2(w);
    }
  }

  for (int i = order.length - 1; i >= 0; --i) {
    final int v = order[i];
    if (!vis[v]) {
      dfs2(v);
      ++compCnt;
    }
  }

  /* ---------- 5. Output result ---------- */
  stdout.writeln(compCnt);
  final sb = StringBuffer();
  for (int v = 0; v < n; ++v) {
    sb.write('${comp[v] + 1}${v == n - 1 ? '\n' : ' '}'); // 1-based ids
  }
  stdout.write(sb.toString());
}

