        // Current item's weight exceeds capacity, skip it
        dp[i][w] = dp[i - 1][w];
      } else {
        // Take maximum of including or excluding the current item
        final includeValue = dp[i - 1][w - weights[i - 1]] + values[i - 1];
        final excludeValue = dp[i - 1][w];
        dp[i][w] = includeValue > excludeValue ? includeValue : excludeValue;
      }
    }
  }

  // Backtrack to find selected items
  final selectedItems = <int>[];
  int currentWeight = capacity;
  for (int i = n; i > 0 && currentWeight > 0; i--) {
    if (dp[i][currentWeight] != dp[i - 1][currentWeight]) {
      selectedItems.add(i - 1); // Add 0-indexed item index
      currentWeight -= weights[i - 1];
    }
  }

  // Print results
  print('Items: ${List.generate(n, (i) => 'Item${i + 1}')}');
  print('Weights: $weights');
  print('Values: $values');
  print('Knapsack capacity: $capacity');
  print('');

  // Print DP table
  print('DP Table:');
  for (int i = 0; i <= n; i++) {
    String row = '';
    for (int j = 0; j <= capacity; j++) {
      row += '${dp[i][j].toString().padLeft(3)} ';
    }
    print(row);
  }
  print('');

  print('Maximum value: ${dp[n][capacity]}');
  print('Selected items (0-indexed): ${selectedItems.reversed.toList()}');

  // Calculate total weight and value of selected items
  int totalWeight = 0;
  int totalValue = 0;
  for (int index in selectedItems) {
    totalWeight += weights[index];
    totalValue += values[index];
  }
  print('Total weight: $totalWeight');
  print('Total value: $totalValue');
}
```

### Explanation:
- **Initialization**: The weights and values are defined, and the knapsack capacity is set to 5.
- **DP Table**: A 2D list `dp` is created with dimensions `(n+1) x (capacity+1)` and initialized to 0.
- **Filling DP Table**: Nested loops iterate over items and capacities, updating the DP table based on whether including the current item yields a higher value.
- **Backtracking**: Starting from the bottom-right of the DP table, it checks which items were selected by comparing values with the previous row.
- **Output**: The code prints the items, weights, values, capacity, formatted DP table, maximum value, selected items (0-indexed and reversed for order), and total weight and value.

This code is efficient and clear, adhering to Dart best practices.

