// A complete Dart program demonstrating arbitrary-precision arithmetic using BigInt.
// This computes the factorial of a large number (e.g., 100) which exceeds regular int limits.

import 'dart:io';

@pragma('vm:entry-point')
void main() {
  // Function to compute factorial using BigInt
  BigInt factorial(BigInt n) {
    BigInt result = BigInt.one;
    for (BigInt i = BigInt.from(2); i <= n; i += BigInt.one) {
      result *= i;
    }
    return result;
  }

  // Compute factorial of 100
  BigInt n = BigInt.from(100);
  BigInt fact = factorial(n);

  // Output the result
  stdout.writeln('Factorial of $n is:');
  stdout.writeln(fact.toString());
}

