@pragma('vm:entry-point')
void main() {
  // Graph represented as adjacency matrix
  // Example graph with 5 vertices
  final int vertices = 5;
  final List<List<int>> graph = [
    [0, 2, 0, 6, 0],
    [2, 0, 3, 8, 5],
    [0, 3, 0, 0, 7],
    [6, 8, 0, 0, 9],
    [0, 5, 7, 9, 0]
  ];

  // Array to track which vertices are included in MST
  List<bool> inMST = List.filled(vertices, false);

  // Array to store the parent of each vertex in MST
  List<int> parent = List.filled(vertices, -1);

  // Array to store the key values (minimum edge weights)
  List<int> key = List.filled(vertices, 999999);

  // Start with vertex 0
  key[0] = 0;
  parent[0] = -1;

  // MST will have V-1 edges
  for (int count = 0; count < vertices - 1; count++) {
    // Find minimum key vertex not yet included in MST
    int minKey = 999999;
    int minVertex = -1;

    for (int v = 0; v < vertices; v++) {
      if (!inMST[v] && key[v] < minKey) {
        minKey = key[v];
        minVertex = v;
      }
    }

    // Add the selected vertex to MST
    inMST[minVertex] = true;

    // Update key values of adjacent vertices
    for (int v = 0; v < vertices; v++) {
      // Update if:
      // - There's an edge between minVertex and v
      // - v is not in MST yet
      // - Weight of edge is less than current key value
      if (graph[minVertex][v] != 0 && 
          !inMST[v] && 
          graph[minVertex][v] < key[v]) {
        parent[v] = minVertex;
        key[v] = graph[minVertex][v];
      }
    }
  }

  // Print the MST
  print('Prim\'s Minimum Spanning Tree:');
  print('Edge \t Weight');
  int totalWeight = 0;

  for (int i = 1; i < vertices; i++) {
    print('${parent[i]} - $i \t ${graph[i][parent[i]]}');
    totalWeight += graph[i][parent[i]];
  }

  print('\nTotal weight of MST: $totalWeight');

  // Test with another graph
  print('\n--- Testing with a different graph ---');

