  final List<List<int>> graph2 = [
    [0, 4, 4, 0, 0, 0],
    [4, 0, 2, 0, 0, 0],
    [4, 2, 0, 3, 2, 4],
    [0, 0, 3, 0, 0, 3],
    [0, 0, 2, 0, 0, 3],
    [0, 0, 4, 3, 3, 0]
  ];

  List<bool> inMST2 = List.filled(vertices2, false);
  List<int> parent2 = List.filled(vertices2, -1);
  List<int> key2 = List.filled(vertices2, 999999);

  key2[0] = 0;
  parent2[0] = -1;

  for (int count = 0; count < vertices2 - 1; count++) {
    int minKey = 999999;
    int minVertex = -1;

    for (int v = 0; v < vertices2; v++) {
